COLLDATA("tadabburur","ur",[[493,"§الزخرف\ndeeds\nکوئی ایسی مصیبت جو آپ کو پہنچی ہویاد کیجئے، پھر کوئی ایسا گناہ یاد کیجئے جو اس مصیبت سے پہلے آپ سے سرزد ہوا ہو،پھراللہ سے توبہ و استغفار کیجئے، عین ممکن ہے کہ یہ مصیبت اسی لئے آئی ہو تاکہ آپ اللہ تعالىٰ سے قریب ہو جائیں.\nاس امت پر تسلسل کے ساتھ آنے والی چھوٹی بڑی مصیبتوں پر غور کیجئے، پھر یہ دعا مانگئے: (اَللّٰهُمَّ إِنِّىْ أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوْبَتِكَ) ‘‘ اے اللہ میں پناہ مانگتا ہوں تیری رضامندی کے ذریعہ تیری ناراضگی سے، اور تیری عافیت کے ذریعہ تیری سزا سے’’.\nصدقہ وخیرات کیجئے، کیونکہ صدقہ اللہ تعالىٰ کے غصہ کو بجھا دیتا اور ٹھنڈا کر دیتا ہے.\nguid\nبندوں پر جو مصیبتیں آتی ہیں وہ اللہ تعالىٰ کی طرف سے ان کے لئے تنبیہ ہوتی ہیں تاکہ وہ توبہ کرلیں اور اللہ تعالىٰ کی طرف لوٹ جائیں.\nاللہ تعالىٰ کی نافرمانیوں، اور اس کے رسول صلی اللہ علیہ وسلم کی مخالفت سے بچو اور دور ہو جاؤ،اللہ تعالىٰ کے غیض وغضب اور اس کے عقاب سے محفوظ رہو گے.\nقول وقرار اور گفتگو میں حد سے تجاوز کرنے سے بچو، کیونکہ اس کا انجام دنیا وآخرت میں رسوائی ہے، چنانچہ قوم فرعون کو دیکھ لیں کہ جب انہوں نے سرکشی کی تو اللہ تعالىٰ نے ان پر اپنا عذاب نازل کردیا.\nrefl\nوَمَا نُرِيهِم مِّنۡ ءَايَةٍ إِلَّا هِيَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ يَرۡجِعُونَ ٤٨\nیہاں اللہ تعالىٰ نے ان کی عذاب کے ذریعہ گرفت کرنے کا سبب بتا دیا، کہ اس سے ان کے -اللہ تعالىٰ کی طرف- لوٹنے کی امید ہے۔ (الشوکانی: ۴؍۵۵۹)\nبندوں کو اللہ تعالىٰ کی طرف سے دنیا میں جو عذاب آتا ہے اس میں بھی اللہ تعالىٰ کی رحمت ظاہر وباہر ہوتی ہے، اس آیت کی روشنی میں اس کی وضاحت کیجئے؟\nوَقَالُواْ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ ٤٩\n(يا أيها الساحر) سے یہاں موسىٰ علیہ السلام مقصود ہیں، اور انہوں نے موسىٰ علیہ السلام کواس طرح یا تو بطور تہکم اور تحقیر وتوبیخ کے مخاطب کیا، یا پھر بطور مدح اس طرح مخاطب کیا، چنانچہ وہ عاجزی کے ساتھ موسى علیہ السلام سےاس انداز میں مخاطب ہوئے جس انداز میں وہ ان لوگوں کے ساتھ مخاطب ہوتے ہیں جنہیں اپنے علماء میں شمار کرتے ہیں، اور وہ جادوگر ہیں۔ (السعدی: ۷۶۷)\nکوئی بھی سوسائٹی علماء اور عبادت گزاروں سے بے نیاز نہیں ہو سکتی، اس آیت کی روشنی میں اس کی وضاحت کیجئے؟\nوَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ ٥١\nیہ اس کی انتہائی درجہ کی جہالت کا نمونہ تھی کہ وہ اچھے اوصاف اور عمدہ افعال کے بجائے ان چیزوں پر فخر کر رہا تھا جو اس کی ذات سے الگ اور خارج تھیں۔(السعدی: ۷۶۷)\nفرعون کا اپنی ذات کی مدح وتعریف کرنے میں بڑی جہالت جھلکتی ہے، اس کی وضاحت کیجئے؟\nفَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةٞ مِّن ذَهَبٍ أَوۡ جَآءَ مَعَهُ ٱلۡمَلَٰٓئِكَةُ مُقۡتَرِنِينَ ٥٣\nیہاں فرعون نے ظاہری شکل کو دیکھا، اور اس معنوی اور باطنی راز کو نہیں سمجھ سکا جو اس سے بھی زیادہ ظاہر وباھر تھا جو اس نے دیکھا تھا، اگر وہ سمجھتا۔ (ابن کثیر: ۴؍۱۳۲)\nفرعون موسىٰ علیہ السلام کو درست اور صحیح نظر سے نہیں دیکھ سکا، اس کی وضاحت کیجئے؟\nفَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ٥٤\nیعنی: فرعون نے اپنى قبطی قوم کو جاہل اور بے وقوف پایا۔ اور یہ بھی کہا گیا ہے کہ: اس نے ان کو کم عقلی اور جہالت پر آمادہ کیا۔ (البغوی: ۴؍۱۰۳)\nسوسائٹی میں بدعات وگمراہی پھیلنے کا ایک بڑا سبب جہالت بھی ہے، اس کی وضاحت کیجئے؟\nفَلَمَّآ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ ٥٥\nعمر بن ذر نے فرمایا: اے اللہ کی نافرمانی کرنے والو!اپنے تئیں اللہ تعالىٰ کے حلم کی وسعت سے دھوکہ نہ کھاؤ، اور اس کے غیض وغضب سے بچو، بیشک اس نے فرمایا ہے: (فلما آسفونا انتقمنا منهم)\" (القرطبی: ۱۹؍۶۴)\nدھوکہ کھانے، اور معصیت میں پڑے رہنے، نیز مسلسل سرکشى کرتے رہنے کی سنگینی بیان کیجئے؟\nفَجَعَلۡنَٰهُمۡ سَلَفٗا وَمَثَلٗا لِّلۡأٓخِرِينَ ٥٦\nچنانچہ ان کی حالت ایسی ہوجاتی ہے کہ کچھ لوگوں کے لئے وہ عبرت وموعظت بن جاتی ہے، جبکہ بعض دیگر لوگوں کے لئے وہی گمراہی کا سبب ہوتی ہے۔ چنانچہ جو یہ فیصلہ کر بیٹھتا ہے کہ انہیں کی طرح رہے، وہ انہیں کی طرح عمل کرتا ہے، اور جو اس چیز سے نجات کی خواہش رکھتا ہے جو ان کو لاحق ہوئی ہے تو وہ ان کے کرتوتوں سے دوری اختیار کرتا اور بچتا ہے۔ (البقاعی: ۷؍۳۹)\nکس طرح اللہ تعالىٰ نے ان کے قصوں کو کسی کے لئے باعث عبرت وموعظت تو کسی کے لئے گمراہی کا سبب بنا دیا ہے؟\nwords\nيَنكُثُونَوه غداري كرتے هيں۔ اپنے كفر پر مصر رهتے هيں.\nمَهِينٌكمزور ۔ جس كي كوئي عزت نه هو.\nمُقتَرِنِينَاس كے ساتھ چپكے هوئے؛ اس كي تصديق كرنے والے.\nآسَفُونَاهميں غصه دلايا."],[494,"§الزخرف\ndeeds\nآپ اور آپ کا کوئی ساتھی پہلى صف میں نماز پڑھنے اور قرآن کی تلاوت کرنے کی باہم وصیت اور اس کا عہد کیجئے.\nاللہ تعالىٰ کی خاطر اپنے کسی بھائی کی زیارت کیجئے، اس طرح کہ اس زیارت سے سوائے اللہ کی خاطر محبت کے اور کوئی چیز مقصود نہ ہو.\nیہ دعا کیجئے: (رَبَّنَا هَبْ لَنَا مِنْ اَزْوَاجِنَا وَ ذُرِّيّٰتِنَا قُرَّةَ اَعْيُنٍ وَّ اجْعَلْنَا لِلْمُتَّقِيْنَ اِمَامًا)۔ ترجمہ: اے ہمارے رب! تو ہمیں ہماری بیویوں اور اولاد سے آنکھوں کی ٹھنڈک عطا فرما اور ہمیں نیک لوگوں کا پیشوا بنادے.\nguid\nدین میں اختلاف کرنے سے بچیں.\nاپنے ہر معاملے میں اللہ کے راستے پر چلیں، اور اس سے بالکل مت ہٹیں.\nوہ دوستیاں جو دنیاوی مصالح اور چاپلوسیوں پر قائم ہوتی ہیں قیامت کے دن دشمنیوں میں تبدیل ہو جائیں گی.\nrefl\nوَإِنَّهُۥ لَعِلۡمٞ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ٦١\nاللہ تعالىٰ کے فرمان: (لعلم للساعة) کا وہ صحیح مطلب جس کی قرآن تائید کرتا ہے، اور متواتر سنت جس کی گواہی دیتی ہے یہ ہے کہ: عیسىٰ علیہ السلام کا آخری زمانے میں نازل ہونا قیامت کی نشانی ہے، یعنی: قیامت کے قریب آنے کی دلیل ہے، اس لئے کہ آپ علیہ السلام - کا نزول- قرب قیامت کی علامتوں میں سے ایک علامت ہے۔ (الشنقیطی: ۷؍۱۲۸)\nاللہ تعالىٰ کے فرمان: (لعلم للساعة) کا کیا مطلب ہے؟\nوَلَا يَصُدَّنَّكُمُ ٱلشَّيۡطَٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ٦٢\nیعنی: على الاعلان اور کھلم کھلا دشمنی رکھنے والا ہے،اور اس دشمنی میں وہ اس قدر آگے بڑھا ہوا ہے کہ اس نے تمارے باپ آدم علیہ السلام کو عیش وآرام اور راحت وسکون کی جگہ سے مشقت وتعب اور تھکاوٹ وبے چینی کی جگہ پہنچا دیا، یہ ایسی عداوت اور دشمنی ہے جو حسد کا نتیجہ ہے، اس لئے یہ کبھی نہیں ختم ہوگی۔ (البقاعی: ۷؍۴۳)\nشیطان کی ہم سے دشمنی کا اصل سبب کیا ہے؟ اور یہ کب ختم ہوگی؟\nإِنَّ ٱللَّهَ هُوَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ٦٤\nیہاں پر: (رَبِّيْ وَ رَبُّكُمْ) عیسىٰ علیہ السلام نے اپنے نفس کو قوم پر مقدم کیا ہے، جس کا مقصد عیسىٰ علیہ السلام کی تقدیس میں غلو کے اسباب کو بند کرنا ہے جس کا ان کے معجزات کیوجہ سے امکان ہے، اس لئے کہ اللہ تعالىٰ جانتا تھا کہ ان کے متبعین میں سے کچھ لوگ ان کے بارے میں غلو کریں گے، اور انھیں حقیقت میں اللہ تعالىٰ کا بیٹا گمان کریں گے۔ (ابن عاشور: ۲۵؍۲۴۸)\nعیسیٰ علیہ السلام نے اپنے قول: (رَبِّيْ وَ رَبُّكُمْ) میں اپنے نفس کو قوم پر کیوں مقدم کیا؟\nٱلۡأَخِلَّآءُ يَوۡمَئِذِۢ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِينَ ٦٧\nیعنی: ہر دوستی اور صحبت جواللہ کے لئے نہیں بلکہ غیر اللہ کے لئے ہوگی، وہ قیامت کے دن دشمنی میں تبدیل ہوجائیگی، تاہم جو دوستی اللہ کے لئے ہوگی وہ ہمیشہ ہمیش باقی رہے گی۔ (ابن کثیر: ۴؍۱۳۵)\nقیامت کے دن دوستی کی پائیداری کا سبب کیا ہوگا؟\nيَٰعِبَادِ لَا خَوۡفٌ عَلَيۡكُمُ ٱلۡيَوۡمَ وَلَآ أَنتُمۡ تَحۡزَنُونَ ٦٨\nیعنی: آنے والے امور ومعاملات میں تمہیں کوئی خوف اور ڈر نہیں ہوگا، اور نہ ہی گزرے ہوئے امور و معاملات میں تمہیں کوئی غم لاحق ہوگا۔ اور جب ہر جانب سے ناپسندیدہ چیز ختم ہوگئی تو اب صرف محبوب اور پسندیدہ چیز بچے گی۔ (السعدی: ۷۶۹)\nجب اہل جنت سے خوف اور غم دور ہوگیا تو پھر ان کے لئے کیا بچا؟\nيُطَافُ عَلَيۡهِم بِصِحَافٖ مِّن ذَهَبٖ وَأَكۡوَابٖۖ وَفِيهَا مَا تَشۡتَهِيهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡيُنُۖ وَأَنتُمۡ فِيهَا خَٰلِدُونَ ٧١ وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ٧٢ لَكُمۡ فِيهَا فَٰكِهَةٞ كَثِيرَةٞ\nجب کھانے اور پینے کا ذکر کر دیا تو اس کے بعد پھلوں کا ذکر کیا تاکہ نعمت اور مسرت مکمل ہوجائے۔ (ابن کثیر: ۴؍۱۳۷)\nکھانے اور پینے کے بعد پھلوں کا ذکر کیوں کیا؟\nوَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ٧٢\nقیامت کے دن ان سے یہ بات کہی جائیگی۔ یعنی: دنیا میں جو نیک اعمال تم کرتے تھے ان کی وجہ سے یہ چیز تم کو ایسے ہی مل گئی جیسے وارث کو میراث ملتی ہے۔ (شوکانی: ۴؍۵۶۴)\nاس آیت کی روشنی میں عمل صالح کی اہمیت پر روشنی ڈالئے؟\nwords\nلَعِلمٌ لِلسَّاعَةِنزول عيسي قرب قيامت كي نشاني هے.\nصِرَاطٌ مُستَقِيمٌجنت كي طرف سيدھا راسته / جس ميں كجي نه هو.\nبِالحِكمَةِنبوت كے ساتھ.\nبَغتَةًأچانك.\nالأَخِلاَّءُدوست و احباب.\nتُحبَرُونَتم خوش ركھے جاؤ گے.\nبِصِحَافٍبرتنوں كے ساتھ."],[495,"§الزخرف\ndeeds\nاس آیت کریمہ کی اتباع کرتے ہوئے اللہ تعالىٰ کی تسبیح بیان کیجئے.\nاللہ تعالىٰ سے دعا کیجئے کہ -قیامت کے دن - آپ اپنے نبی محمد صلی اللہ علیہ وسلم کی شفاعت سے شرف یاب ہوں.\nآج جس نے آپ پر ظلم کیا ہو اسے معاف کردیں.\nguid\nاللہ تعالىٰ کا تمام چیزوں پر محیط ہونا، اور اس کی علمی وسعت بندے کو اس بات کی طرف دعوت دیتی ہے کہ وہ اللہ تعالىٰ کو ہمیشہ نگہبا ن اورمطلع سمجھے، اس سے ڈرے اور اس کا تقوى اختیار کرے.\nکافروں نے اللہ تعالىٰ کی طرف جس طرح بیٹے کی نسبت کی ہے اس سے اس کی پاکی بیان کرنی چاہیئے.\nاللہ نے اپنے نبی محمد صلی اللہ علیہ وسلم کو کافروں سے در گزر اور اعراض کرنے کے لئے کہا ہے، تو ہمیں بھی چاہیئے کہ جو لوگ ہمیں تکلیف دیں ہم ان سے در گزر کریں.\nrefl\nلَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِيهِ مُبۡلِسُونَ ٧٥\nیہاں پر (مبلس)سے مراد وہ شخص ہے جو نجات سے مایو س ہو چکا ہو، ایسا شخص جو مایوسی کا شکار ہو کر خود کو عذاب اور بلاء ومصیبت کے حوالے کرچکا ہو۔ (الطبری: ۲۱؍۶۴۳)\nجہنم میں کفار کی مایوسی سے کیا مراد ہے؟\nلَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِيهِ مُبۡلِسُونَ ٧٥\nیعنی: مایوسی کی شدت سے بہت غمگین ہوں گے۔ راغب نے فرمایا: “إِبْلَاس” ایسے غم کو کہتے ہیں جو شدید مایوسی کا نتیجہ ہو۔ بعض لوگوں کا کہنا ہے کہ اسی سے ابلیس کا لفظ بھی مشتق ہے۔ اور جب حال یہ ہے کہ مُبْلِسٌآدمی اکثر خاموش رہتا ہے، اور اپنے کام کی چیز بھول جایا کرتا ہے، تو اسی بنا پر کہا جاتا ہے: أَبْلَسَ فُلَانٌ: جب وہ خاموش ہوجائے، اور اس کی دلیل اور حجت کٹ جائے اور بے وقعت ہوجائے”۔ اور یہاں پر إِبْلَاس کی تفسیر خاموشی اور حجت کی نا تمامی اور دلیل کی نامرادی سے کی گئی ہے۔ (الألوسی: ۲۵؍۱۴۱)\n(مُبْلِسُوْنَ) کا کیا معنى ہے؟\nقَالَ إِنَّكُم مَّٰكِثُونَ ٧٧ لَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ ٧٨\nجب جہنمیوں نے موت کی مانگ کی تب جہنم کے داروغہ مالک نے ان کو جواب دیتے ہوئے کہا: (قال إنكم ماكثون)،پھر ان کی بدبختی کا سبب بتایا کہ وہ -یعنی سبب- ان کی حق کی مخالفت اور اس کا انکار ہے، چنانچہ کہا: (لقد جئناكم بالحق ولكن أكثركم للحق كارهون) (ابن کثیر: ۴؍۱۳۷)\nاللہ تعالىٰ کے قول: (لقد جئناكم بالحق) کے بعد اس قول: (قال إنكم ماكثون) کا کیا فائدہ ہے؟\nلَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ ٧٨\nہم آپ کے پاس دنیا میں حق لے کر آئے،اور وہ حق توحید اور ہر وہ چیز ہے جس پر ایمان لانا واجب ہے، اور یہ چیز رسولوں کو بھیج کر اور کتابوں کو نازل کرکے انجام پائی، لیکن تم میں سے اکثر لوگ حق کو -چاہے وہ جس قسم کا ہو- ناپسند کرتے تھے، چنانچہ وہ اسے قبول نہیں کرتے تھے، بلکہ اس سے نفرت کرتے اور دور بھاگتے تھے۔ (الألوسی: ۲۵؍۱۴۲)\nآیت میں مذکور (حق) سے کیا مراد ہے؟\nقُلۡ إِن كَانَ لِلرَّحۡمَٰنِ وَلَدٞ فَأَنَا۠ أَوَّلُ ٱلۡعَٰبِدِينَ ٨١\n(فأنا أول العابدين) یعنی: اس بچے کی سب سے پہلے عبادت کروں گا، اس لئے کہ وہ اپنے باپ کا ایک حصہ ہوگا، اور میں اللہ تعالىٰ کے پسندیدہ امور کو بجا لانے میں مخلوقات میں سب سے زیادہ مستحق اور حقدار ہوں۔ لیکن حقیقت یہ ہے کہ میں اس چیز کا سب سے پہلا منکر، اور سب سے سخت نفی کرنے والا ہوں، پس اس بات سے اس کا بطلان واضح ہوجاتا ہے۔ چنانچہ یہ اس شخص کے لئے بہت بڑی دلیل ہے جو رسولوں کے احوال جانتا ہے، کیونکہ جب وہ جان لے گا کہ رسول مخلوقات میں سب سے کامل ہوتے ہیں، اور ہر خیر کے کام کو وہ سب سے پہلے پورى طرح انجام دیتے ہیں، اور ہر شر کو وہ سب سے پہلے چھوڑتے، اس کا انکار کرتے، اور اس سے دور ہوجاتے ہیں، تو اگر عیسىٰ علیہ السلام اللہ تعالىٰ کے بیٹے ہوتے تو آپ صلی اللہ علیہ وسلم سب سے پہلے ان کی عبادت کرتے، اور یہ مشرکین آپ سے سبقت نہ لے جا پاتے۔ (السعدی: ۷۷۰)\nاس آیت سے یہ پتہ چلتا ہے کہ رسول خیر وکمال کے باب میں سب سے آگے ہوتے ہیں، جبکہ شرور ونقائص اور کمی کوتاہی میں سب سے دور ہوتے ہیں۔ آیت سے اس فائدہ کی وجہ بتائیے؟\nسُبۡحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ ٨٢\nآسمان وزمین کے ذکر کرنے کا مقصد تدبیر وخلق کی دنیا کا احاطہ ہے، اس لئے کہ مشرکین نے زمین میں نصب کردہ بتوں کی شکل میں اللہ کا شریک بنا رکھے تھے، اور آسمان میں فرشتوں کی شکل میں شریک ٹھہرا رکھے تھے، کیونکہ فرشتوں کو وہ اللہ کی بیٹیاں گردانتے تھے۔ (ابن عاشور: ۲۵؍۲۶۷)\nاس آیت نے اللہ تعالىٰ کی ربوبیت کے ساتھ صرف آسمان وزمین ہی کو کیوں خاص کیا؟\nفَٱصۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَٰمٞۚ فَسَوۡفَ يَعۡلَمُونَ ٨٩\nیہاں ان کو معروف اور متداول سلام کرنے کا حکم نہیں دیا گیا ہے، بلکہ یہ درحقیقت ان کو چھوڑنے اور ان سے جان چھڑانے کا حکم ہے۔ اور اس کا حاصل یہ ہے کہ: اگر تم انکار کرتے ہو ، اور میری بات نہیں مانتے ہو تو میرا مقصد تم سے جان چھڑانا ، اعراض کرنا اور تمہارے شر سے بچناہے۔ (الألوسی: ۲۵؍۱۵۱)\nہمیں یہ حکم دیا گیا کہ ہم اس وقت نرمی اور حکمت سے کام لیں جب ہمارے مدعویین -یعنی: جنہیں ہم دعوت دیتے ہیں- انکار کریں اور عناد وسرکشی سے کام لیں۔ آیت کی روشنی میں اس کی وضاحت کیجئے؟\nwords\nلاَ يُفَتَّرُ عَنهُمان پر عذاب هلكا نه كيا جائے گا.\nمُبلِسُونَالله تعاليٰ كي رحمت سے مايوس.\nأَم أَبرَمُوا أَمرًانبي كريم صلی اللہ علیہ وسلم كے خلاف پخته چال چلي.\nيَخُوضُواوه باطل كلام كرتے هيں.\nفَأَنَّى يُؤفَكُونَوه كيسے الله كي عبادت سے رو گرداني كرتے هيں.\nوَقِيلِهِمحمد صلی اللہ علیہ وسلم كا كلام جو كه اپنے شكوه ميں كها.\nفَاصفَحان كو ايذاء رساني سے منه موڑا/ ان كو معاف كرو."],[496,"§الدخان\ndeeds\nجب آپ صبح بیدار ہوں تو یہ دعا پڑھیں: (اَلْحَمْدُ لِلّٰهِ الَّذِیْ أَحْيَانِىْ بَعْدَ مَا أَمَاتَنِىْ وَإِلَيْهِ النُّشُوْرُ) اس اللہ کے لئے ساری تعریفیں ہیں جس نے مجھے موت دینے کے بعد زندہ کیا، اور اسی کی طرف دوبارہ لوٹنا ہے.\nاللہ تعالىٰ سے دعا کریں کہ وہ پریشان حال لوگوں کی پریشانیاں دور کرے.\nآپ صلی اللہ علیہ وسلم کی تعظیم کرتے ہوئے آپ پر درود بھیجیں.\nguid\nقرآن کا نزول، اور روزی کی تقسیم شب قدر کے فضائل میں سے ہے، لہٰذا اسے غنیمت جانیے، اور قیام اللیل، ذکر و دعا اور تلاوت قرآن کے ذریعہ اسے زندہ کیجئے.\nجب اللہ تعالىٰ کی یاد دلائی جائے تو اسے یاد کریں، اور تکبر کا شکار نہ ہوں، مبادا ایسا نہ ہو کی اللہ تعالىٰ آپ کی بصیرت کو ختم کردے.\nاللہ تعالىٰ رسی ڈھیلی کرتا ہے، مگر مطلق چھوڑتا نہیں ہے.\nrefl\nإِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِينَ ٣\n(فِي لَيلَةٍ مُبَارَكَةٍ) یعنی: بہت زیادہ خیر وبرکت والی رات۔ یہ ایسی رات ہے جو ہزار مہینوں سے بہتر ہے، چنانچہ سب سے بہتر کلام -قرآن- کو سب سے بہتر رات ودن میں، سب سے بہتر مخلوق -یعنی: محمد صلی اللہ علیہ وسلم- پر، عربی زبان میں نازل کیا گیا۔ (السعدی: ۷۷۳)\nمبارک رات سے کیا مراد ہے؟ اور اسے برکت والی کیوں کہا گیا؟\nفِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ ٤\n(يفرق) کا مطلب ہے: طے کیا جاتا ہے اور فیصلہ کیا جاتا ہے۔ اور (أمر حكيم) کا مطلب: بندوں کے ارزاق ، ان کی عمریں، اور ان کے اس سال کے تمام معاملات ہیں، اسی مبارک رات یہ لوح محفوظ سے لئے جاتے ہیں تاکہ آنے والے پورے سال فرشتے اس کو بجا لاتے رہیں۔ (ابن جزی: ۲؍۳۲۱)\nوہ (أمر حكيم) کیا ہے جس کا شب قدر میں فیصلہ کیا جاتا ہے؟\nبَلۡ هُمۡ فِي شَكّٖ يَلۡعَبُونَ ٩\nان کا اقرار علم اور پختہ یقین کا نتیجہ نہیں ہے، بلکہ وہ نہ کی طرح ہے، کیونکہ انہوں نے اس یقین کو شک اور لا پرواہی وکھلواڑ کے ساتھ ملادیا ہے، چنانچہ ان کے اقرار میں یقین کی خاصیت باقی نہیں رہی، اور نہ ہی وہ یقین باقی رہا جو علم کے تقاضوں سےہم آہنگ ہوتا ہے۔ اور ہوتا یہ ہے کہ اگر علم انسان کو عمل پر آمادہ نہ کرسکے، اور صاحب علم گاہے بگاہے اس علم پر نظر نہ ڈالتا رہے، تو نتیجہ یہ نکلتا ہے کہ وہ غفلت ونسیان کا شکار ہو جاتا ہے، اور پھر اس کا یقین شک میں تبدیل ہونے لگتا ہے۔ (ابن عاشور: ۲۵؍۲۸۵-۲۸۴)\nاس آیت کی روشنی میں علم کے مطابق عمل نہ کرنے کی سنگینی واضح کیجئے؟\nفَٱرۡتَقِبۡ يَوۡمَ تَأۡتِي ٱلسَّمَآءُ بِدُخَانٖ مُّبِينٖ ١٠\nابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: ان چھ چیزوں سے پہلے نیک اعمال کرلو: دجال، دھواں، زمیں سے نکلنے والا چوپایہ، سورج کا مغرب سے طلوع ہونا،وہ فتنہ جو عوام میں پھیل جائے، اورتمہارى موت کا آجانا۔ (البقاعی: ۷؍۶۸)\nکسی کام کو ٹالتے رہنے اور نیک عمل کو مؤخر کرنے میں کیا قباحتیں ہیں؟\nرَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ ١٢\n(إنا مؤمنون) کا جملہ ان سے عذاب ٹالنے کی گزارش کی علت ہے، یعنی: ہمارے ساتھ وہ عمل ہے جو ہم سے کافروں کو ملنے والا عذاب ہٹا سکتا ہے۔ اور یہاں ان کو اس بات کی تلقین کرنے سے ایمان کے شرف وعظمت کا پتہ چلتا ہے۔ (ابن عاشور: ۲۵؍۲۹۰)\nاس آیت کریمہ سے ایمان کے شرف وعظمت کا پتہ کیسے چلتا ہے؟\n۞وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَآءَهُمۡ رَسُولٞ كَرِيمٌ ١٧\nقتادہ سے مروی ہے کہ انہوں نے اللہ تعالىٰ کے فرمان: (رَسُوْلٌ كَرِيْمٌ) کے بارے میں کہا کہ اس سے مراد موسىٰ علیہ السلام ہیں۔ اور انہیں اللہ تعالىٰ نے کریم اس لئے کہا ہے کیونکہ وہ اللہ تعالىٰ کے یہاں معزز ومکرم اور بلند مرتبہ والے تھے۔ اور یہ بھی جائز ہے کہ انہیں کریم اس لئے کہا گیا کیونکہ وہ اپنی قوم میں شریف، عزت دار اور صاحب حیثیت تھے۔ (الطبری: ۲۲؍۲۴)\nاللہ کے نبی موسىٰ علیہ السلام کو کریم کی صفت سے کیوں متصف کیا گیا؟\nإِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ١٨\nیعنی: اللہ رب العالمین کی طرف سے رسول بنا کر بھیجا گیا ہوں، جس چیز کو دے کر بھیجا ہے اس کے تئیں امانت دار ہوں، تم لوگوں سے اس میں سے کوئی چیز نہیں چھپاتا ہوں، اور نہ ہی اس میں اپنی طرف سے کچھ بڑھاتا گھٹاتا ہوں۔ اور یہ ایسی چیز ہے جو آپ صلی اللہ علیہ وسلم کی اطاعت واتباع کو واجب کرتى ہے۔ (السعدی: ۷۷۳)\nاس آیت میں بدعت اور اسے ایجاد کرنےکی مذمت ہے۔ اسے واضح کیجئے؟\nwords\nلَيلَةٍ مُبَارَكَةٍشب قدر / ماه رمضان ميں ايك رات.\nيُفرَقُفيصله كيا جاتا هے(لوح محفوظ سے ملائكه كي كتب كي طرف احكام كا نزول).\nأَمرٍ حَكِيمٍامر محكم / مضبوط كام.\nفَارتَقِبپس تم انتظار كرو(ان مشركين كا).\nالبَطشَةَ الكُبرَىقيامت كے دن كا سخت عذاب.\nأَدُّوا إِلَيَّبني اسرائيل ؛ الله كے بندوں كو ميرے سپرد كرو."],[497,"§الدخان\ndeeds\nجس سے آپ کو خوف ہے، چاہے وہ آپ کا دشمن ہو، یا کوئی تکلیف، یا اس طرح کی کوئی چیز، اس سے اللہ کی پناہ طلب کیجئے.\nکسی ایسے کافر کو یاد کیجئے، جو بڑا مجرم ہو اور اس نے مومنوں کو حد درجہ تکلیف پہنچائی ہو، اور اس پر بد دعا کیجئے.\nکسی ایسی جگہ دو رکعت نماز پڑھیئے جہاں اس سے پہلے آپ نہ پڑھے ہوں، تاکہ وہ آپ کے لئے گواہی دے.\nguid\nمومن کے نیک عمل کی وجہ سے اس کی موت پر آسمان و زمین روتے ہیں، چنانچہ آپ نیک عمل کریں، تاکہ آپ کے لئے بھی ایسا ہی ہو.\nاللہ تعالىٰ ظالموں کو ہلاک کرنے پر قادر ہے.\nان اسباب سے بچو جن کی بنا پر امتیں ہلاک ہو گئیں.\nrefl\nوَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ ٢١ فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوۡمٞ مُّجۡرِمُونَ ٢٢\n(وإن لم تؤمنوا لي فاعتزلون) یعنی: میرے پیچھے مت پڑو، اور اس معاملے کو ہمارے درمیان اسی طرح امن وامان کے ساتھ پڑے رہنے دو یہاں تک کہ اللہ تعالىٰ ہمارے درمیان فیصلہ کردے۔ چنانچہ جب وہ ایک لمبی مدت تک ان کے درمیان رہے، اور ان پر اللہ تعالىٰ کی حجتیں قائم کردیں، مگر جب اس نے محض ان کے کفر و سرکشی میں اضافہ کیا، تو انھوں نے ان پر اللہ تعالىٰ سے ایسی بد دعا کی جس نے انہیں آلیا۔ (ابن کثیر: ۴؍۱۴۳)\nکس چیز نے موسىٰ علیہ السلام کو اس بات پر مجبور کیا کہ وہ فرعون اور اس کی قوم کے حق میں دعا سے بد دعا کی طرف پلٹ گئے؟\nفَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ\nیعنی: نہ تو ان کے ایسے نیک اعمال تھے جو آسمان میں جاتے رہے ہوں، تو آسمان اب ان کے انقطاع پر آنسو بہائے، اور نہ زمین میں کسی جگہ انہوں نے عبادت کی تھی کہ زمین ان کی عدم موجودگی محسوس کرے، لہٰذا وہ اس بات کے مستحق قرار پائے کہ ان کے کفر وعناد اور جرم وسرکشی کیوجہ سے نہ ان کی طرف دیکھا جائے، اور نہ ہی ان کا معاملہ مؤخر کیا جائے۔ (ابن کثیر: ۴؍۱۴۴)\nآسمان وزمین بندوں پر کس وجہ سے روتے ہیں؟\nفَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ ٢٩\nیہ ان کی ہلاکت و بربادی کی کوئی پرواہ نہ کرنے کا بیان ہے۔ مفسرین نے اس کی وضاحت کرتے ہوئے کہا ہے کہ اس کا مطلب یہ ہے کہ نہ تو وہ زمین پر کوئی ایسا نیک عمل کرتے تھے جس کی وجہ سے ان پر رویا جائے، اور نہ ہی آسمان میں ان کا کوئی ایسا اچھا عمل جاتا تھا جس کی وجہ سے ان پر رویا جائے۔ مطلب یہ ہے کہ ان کی ہلاکت سے زمین وآسمان میں کسی کو کوئی تکلیف نہیں ہوئی نہ کسی کو کوئی غم پہنچا۔ (الشوکانی: ۴؍۵۷۵)\nاس آیت کی روشنی میں کافروں کی ذلت و رسوائی کی وضاحت کیجئے؟\nوَلَقَدِ ٱخۡتَرۡنَٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَٰلَمِينَ ٣٢ وَءَاتَيۡنَٰهُم مِّنَ ٱلۡأٓيَٰتِ مَا فِيهِ بَلَٰٓؤٞاْ مُّبِينٌ ٣٣\nچونکہ قریش دنیا کے ظاہری سازو سامان اور مادی نعمتوں کی بنا پر فخر کرتے تھے، اور اسے اللہ تعالىٰ کی طرف سے تعظیم اور بڑی چیز سمجھتے، نیز دنیاوی امور میں کمزوری کو شقاوت اور اللہ تعالىٰ سے دور ى گردانتے تھے، اس لئے اللہ تعالىٰ نے ان پر رد کرتے ہوئے اس چیز کا ذکر کیا جو اس نے فرعون کو ہلاک وبرباد کرنے اور اس کا مکمل صفایا کرنے کے بعد بنی اسرائیل کو باوجود ضعف وکمزورى اور بد حالی کےعطا کیا ۔ (البقاعی: ۷؍۷۶)\nکیا دنیا میں مالدارى ، مالدار بندے سے اللہ کی محبت کی دلیل ہے؟\nأَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ ٣٧\nاللہ تعالىٰ نے جب قوم فرعون کی ہلاکت کا ذکر کردیا، تو کفار مکہ کے لئے ایک اور ایسی مثال کا ذکر کیا جس سے وہ فرعون کے مقابلے میں زیادہ عبرت پکڑ سکتے تھے، اور وہ ایسی قوم کی ہلاکت کے بارے میں تھا جو فرعون کے مقابلے ان سے زیادہ قریب تھی، اور وہ قومِ تبّع ہے۔ کیونکہ عرب برابر تبع کے بادشاہ اور اس کی قوم کے عظمت کے بارے میں سنتے رہتے تھے، اور بہت سارے عربوں نے اپنے مختلف اسفار میں ان کی قوت وعظمت کے آثار کو دیکھ رکھا تھا،اور سیل عرم کے سبب جو ہلاکت ان کے حصے میں آئی تھی اس کے بارے میں وہ آپس میں گفتگو کرتے رہتے تھے۔ (ابن عاشور: ۲۵؍۳۰۸)\nقوم تبع کی مثال بیان کرنے کا کیا فائدہ ہے؟\nأَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ ٣٧\nاس آیت کا مطلب یہ ہے کہ: کیا قریش زیادہ مضبوط اور قوی ہیں یا تبع کی قوم اور وہ کفار ومشرکین جو ان سے پہلے تھے؟ اور ہم نے جس طرح قوم تبع اور دیگر قوموں کو کفر کے سبب ہلاک وبرباد کردیا اسی طرح ان کو بھی ہلاک کردیں گے۔ گویا یہاں مقصد دھمکی دینا ہے۔ (ابن جزی: ۲؍۳۲۴)\nآیت کریمہ میں موجود دھمکی کی شرح کیجئے؟\nوَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ ٣٨ مَا خَلَقۡنَٰهُمَآ إِلَّا بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٣٩\nتو یہ اسی -یعنی: یہ نہ جاننے کیوجہ سے کہ اللہ تعالىٰ نے مخلوقات کو کیوں پیدا کیا ہے-بنا پر معصیت و نا فرمانی کی جرأت کرتے اور زمین میں فساد مچاتے ہیں، کیونکہ نہ تو یہ کسی ثواب کی امید رکھتے ہیں، اور نہ ہی کسی عذاب وعقاب سے ڈرتے ہیں۔ (البقاعی: ۷؍۷۹)\nبندے کو کونسی چیز معاصى اور فساد پر جرى بناتی ہے؟ اور کونسی چیز اس کو استقامت اور نیکی پر ابھارتی ہے؟\nwords\nوَأَن لاَ تَعلُوااور يه كه تم تكبر نه كرو.\nبِسُلطَانٍدليل اور حجت كے ساتھ.\nعُذتُميں نے پناه مانگي.\nأَن تَرجُمُونِكه تم مجھے پتھر مار كر رجم كرو.\nرَهوًاساكن / جس ميں حركت و اضطراب نه هو.\nمُنظَرِينَجن كي سزا مؤخر كردي گئي هو.\nاختَرنَاهُمهم نے ان كو چن ليا.\nبِمُنشَرِينَدوباره اٹھائے جانے والے."],[498,"§الدخان\ndeeds\nاللہ تعالىٰ سے دعا کریں کہ وہ فیصلے -قیامت- کے دن آپ پر رحم کرے.\nآپ یہ دعا کریں: (اَللّٰهُمَّ إِنِّىّْ أَعُوْذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ وَعَمَلٍ)۔ ‘‘ الٰہی! میں جہنم اور جہنم کی طرف جانے والے قول و عمل سے تیری پناہ چاہتا ہوں.\nاللہ تعالىٰ سے دعا کیجئے کہ آپ ان لوگوں میں سے ہوں جو باغات اور بہتے ہوئے پانی کے چشموں کے درمیان چین کی جگہ میں ہوں گے.\nguid\nقیامت کے دن کفار ومشرکین جس عذاب اور ذلت ورسوائی کا سامنا کریں گے وہ بڑی شدید ہوگی.\nمومن کو جو بھی نعمتیں عطا ہوں گی وہ محض اللہ تعالىٰ کے فضل وکرم اور احسان کا نتیجہ ہوں گى.\nنزولِ قرآن کے اغراض ومقاصد میں ایک اہم غرض ذکر وموعظت اور نصیحت ہے.\nrefl\nإِلَّا مَن رَّحِمَ ٱللَّهُۚ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ٤٢\nیعنی: اللہ تعالىٰ اس قدر (العزيز) اور غالب وقوی ہے کہ اسے کوئی اس کے ارادے اور مقصد سے موڑ نہیں سکتا، چنانچہ وہ جس پر چاہتا ہے محض اپنی مشیئت و مرضی سے رحم کرتا ہے۔ اور وہ (الرحيم) ہے، یعنی: کشادہ رحمت والا ہے، اپنے علم وحکمت اور وعدے کے مطابق جس پر چاہتا ہے رحم کرتا ہے۔ حدیث شریف میں آیا ہے: “زمین والوں پر رحم کرو تو آسمان والا تم پر رحم کریگا”۔(ابن عاشور: ۲۵؍۳۱)\nاس آیت کریمہ کو (العزيز) اور (الرحيم)کے دونوں ناموں سے ختم کرنے میں کیا حکمت ہے؟\nذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ ٤٩\nیہ بات کافر کو ڈانٹتے اور پھٹکارتے ہوئے کہی جائیگی ، یعنی: تم اپنے آپ کو دنیا میں بہت عزیز اور کریم سمجھتے تھے، اور بڑے عزت دار بنے پھرتے تھے۔ بعض روایتوں میں آتا ہے کہ ابو جہل نے کہا کہ مکہ کے دونوں پہاڑوں کے درمیان کوئی مجھ سے زیادہ عزیز اور کریم نہیں ہے۔ اس پر یہ آیت نازل ہوئی۔ (ابن جزی: ۲؍۳۲۴)\nقیامت کے دن جب کافر عذاب میں مبتلا ہوگا تو ایسی حالت میں اسے عزیز و کریم کیسے کہا جائیگا؟\nإِنَّ ٱلۡمُتَّقِينَ فِي مَقَامٍ أَمِينٖ ٥١\nکسی جگہ کی خوبصورتی کے لئے سب سے ضروری چیز امن وامان ہے، اس لئے کہ کہیں بھی رہنے والا شخص سب سے پہلے ناپسندیدہ اور خوفناک چیزوں سے امن وامان چاہتا ہے، لہٰذا جب وہ اپنے ٹھکانے میں مطمئن ہوگا، تبھی ملنے والی نعمتوں کو صحیح سے محسوس کریگا، اور اس سے لذت اٹھائے گا۔ (ابن عاشور: ۲۵؍۳۱۷)\nاس آیت کریمہ کی روشنی میں امن وامان کی عظیم نعمت کو واضح کیجئے؟\nيَلۡبَسُونَ مِن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَقَٰبِلِينَ ٥٣\nکوئی بھی جنتی اس طرح نہیں بیٹھے گا کہ اس کی پیٹھ کسی کی طرف ہو، بلکہ سب رو برو ہوں گے۔ (ابن کثیر: ۴؍۱۴۸)\nجنت میں ادنى قسم کی بھی توہین اور بے عزتی کا سامان نہیں ہوگا۔ اس آیت کی روشنی میں اس کی وضاحت کیجئے؟\nيَدۡعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ ٥٥\nاللہ تعالىٰ فرماتا ہے: جنت کے پھل ان پھلوں کی طرح نہیں ہوں گے جو ہم دنیا میں کھاتے ہیں، اور کھاتے ہوئے بسا اوقات اس کے برے نتیجے، اور اس سے پہنچنے والی کسی تکلیف سے ڈرتےبھی ہیں، ساتھى ہی ساتھ ان کے ختم ہونے اور بعض اوقات نہ ملنے کا بھی اندیشہ رہتا ہے۔ (الطبری: ۲۲؍۵۳)\nیہاں پھل کو امن کے ساتھ کیوں ذکر کیا گیا ہے؟\nفَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ٥٨\nیعنی: اس قرآن کو ہم نے آسان کردیا ہے، سہل اور واضح ترین بنا کر آپ کی اس زبان میں نازل فرمایا ہے جو سب سے فصیح واضح شیریں اور بلند پایہ ہے۔ (ابن کثیر: ۴؍۱۴۹)\nاس آیت کی روشنی میں عربی زبان کی دیگر تمام زبانوں پر فضیلت کے تئیں گفتگو کیجئے؟\nفَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ ٥٩\nیعنی: آپ ہمارى طرف سے آپ کو پہنچنے والى مدد، اور ان کی ہلاکت کا انتظار کیجئے، کیونکہ وہ اس کے برعکس انجام ونتیجے کا انتظار کر رہے ہیں۔ چنانچہ اس میں آپ صلی اللہ علیہ وسلم کے لئے وعدہ اور ان کے لئے وعید اور دھمکی ہے۔ (ابن جزی: ۲؍۳۲۵)\nاس آیت نے کس طرح وعد اور وعید کو جمع کیا ہے اس کی شرح کیجئے؟\nwords\nالأَثِيمِبهت بڑا گنهگار.\nكَالمُهلِپگھلتي هوئي معدنيات كي طرح.\nفَاعتِلُوهُاسے كھينچو؛ اور سختي كركے عذاب كي طرف لے جاؤ.\nسُندُسٍباريك ريشم.\nوَإِستَبرَقٍموٹا ريشم.\nالمَوتَةَ الأُولَىوه جس كا ذائقه دنيا ميں هي چكھ ليا.\nفَارتَقِباپني نصرت اور ان كي هلاكت كا انتظار كرو."],[499,"§الجاثيہ\ndeeds\nانسان، اونٹ، اور سانپ کے چلنے پر غور کیجئے، ان کی چالوں کے درمیان فرق کو لکھئے، اور یہ بتائیے کہ یہ فرق و اختلاف کس چیز پر دلالت کرتا ہے.\nرات اور دن کے بدلنے اور ان کے آگے پیچھے آنے جانے میں جوفوائد اورمنافع مضمر ہیں ان میں سے تین فائدے نوٹ کیجئے.\nکوئی ایسا گناہ جو آپ سے سرزد ہوا ہے اسے یاد کیجئے، پھر کوئی آیت جو اس گناہ سے روکتی ہو اسے یاد کیجئےاور اللہ تعالىٰ سے توبہ واستغفار کیجئے.\nguid\nجب آپ کے پاس اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے پاس سے علم آجائے تو اسے اپنے لئے کافی سمجھیں، اور لوگوں کی خواہشات کی پیروی نہ کریں.\nخبردار جو آپ کسی ایسی چیز کا مذاق اڑائیں جس کا تعلق دین سے ہو، کیونکہ اس کا گناہ بہت بڑا ہے.\nاللہ کی مخلوقات میں غور وفکر کرنامنجملہ ان نفع بخش اور مفید ترین چیزوں میں سے ہے جو اللہ تعالىٰ کا شکر بجا لانے اور تنہا اس کی عبادت کرنے پر بندے کی مدد کرتی ہیں.\nrefl\nتَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ٢\nیہاں اللہ تعالىٰ نے (العزيز الحكيم) کی صفتوں کو اپنے دیگر خوبصورت ترین ناموں پر ترجیح دیتے ہوئے ذکر کیا ہے، کیونکہ (العزيز) کی صفت یہ بتلاتی ہے کہ جو کچھ اللہ تعالىٰ نے نازل کیا ہے وہ اسکی عزت وقوت کے مناسب اور لائق وزیبا ہے، جیسا کہ ایک دوسری جگہ اللہ تعالىٰ نے اس کتاب کو (العزيز) کی صفت سے متصف کرتے ہوئے فرمایا ہے: ﴿إِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ﴾ [فصلت: ٤١]، یعنی: اور بیشک وہ کتاب عزیز ہے۔ مطلب یہ ہے کہ وہ ایسی کتاب ہے جو اپنے مخالفین پر غالب اور ان کو پست کرنے والی ہے، اس لئے کہ اس نے انہیں اپنے ہم مثل لانے سے عاجز کردیا۔ اور (الحكيم) کی صفت یہ پیغام دیتی ہے کہ جو کچھ اللہ تعالىٰ کے پاس سے نازل ہوا ہے وہ اس کی حکمت کے عین مطابق ہے۔ (ابن عاشور: ۲۵؍۳۲۵)\nیہاں دیگر اسماء حسنىٰ کو چھوڑ کر صرف (العزيز الحكيم) ہی کے ناموں کو ہی کیوں ذکر کیا گیا؟\nلَأٓيَٰتٖ لِّلۡمُؤۡمِنِينَ ٣ ءَايَٰتٞ لِّقَوۡمٖ يُوقِنُونَ ٤ ءَايَٰتٞ لِّقَوۡمٖ يَعۡقِلُونَ ٥\nپہلے (لآيات للمؤمنين) کہا، پھر (يوقنون) کہا، پھر (آيات لقوم يعقلون) کہا۔ اور اس میں ایک بہترین اور شریف حالت سے اس سے زیادہ بہترین، اعلى اور شریف حالت کی طرف منتقلی اور ترقی ہے۔ (ابن کثیر: ۴؍۱۵۰)\nمومنین کی صفت بیان کرتے وقت پہلے ایمان، پھر یقین، پھر عقل کو اس ترتیب سے کیوں ذکر کیا؟\nإِنَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّلۡمُؤۡمِنِينَ ٣ وَفِي خَلۡقِكُمۡ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٞ لِّقَوۡمٖ يُوقِنُونَ ٤ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزۡقٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِيفِ ٱلرِّيَٰحِ ءَايَٰتٞ لِّقَوۡمٖ يَعۡقِلُونَ ٥\nیہاں توحید کے چھ ایسے قوی دلائل ذکر کئے گئے ہیں جو اللہ تعالىٰ کی عظمت وجلال، اس کے کمال قدرت، اور اس بات پر دلالت کرتے ہیں کہ صرف وہی عبادت کے لائق ہے: (۱) آسمان وزمین کو پیدا کرنا،(۲) لوگوں کو پیدا کرنا،(۳) چوپایوں کو پیدا کرنا، (۴)رات ودن کا بدلتے رہنا،(۵) آسمان سے بارش کا نازل کرنا، اور اس سے زمین کو زندہ کرنا،(۶) ہواؤوں کو چلانا۔ (الشنقیطی: ۷؍۱۷۹)\nاس آیتوں میں اللہ تعالىٰ نےچھ ایسے قوی دلائل کا ذکر کیا ہے جو اس کی عظمت وجلالت پر دلالت کرتی ہیں، وہ کیا ہیں؟\nوَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزۡقٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا\nاور جو اللہ تعالىٰ نے ضرورت کے وقت بادلوں سے بارش نازل کی۔ یہاں بارش کو رزق سے تعبیر کیا کیونکہ اس سے رزق کا حصول ہوتا ہے۔ (ابن کثیر: ۴؍۱۵۰)\nاللہ تعالىٰ نے بارش کو رزق کا نام کیوں دیا؟\nوَيۡلٞ لِّكُلِّ أَفَّاكٍ أَثِيمٖ ٧ يَسۡمَعُ ءَايَٰتِ ٱللَّهِ تُتۡلَىٰ عَلَيۡهِ ثُمَّ يُصِرُّ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٖ ٨\nاس صفت سے یہ بات معلوم ہوئی کہ جسے قرآن کی آیتیں -معاصی ومنکرات اور عناد ونافرمانی سے- نہ روک سکیں تو وہ کوئی گناہ اور جھوٹ میں ڈوبا ہوا شخص ہوگا، چنانچہ ایسے شخص کے لئے بربادی اور ہلاکت ہے۔ (البقاعی: ۷؍۹۳)\nجو قرآنی ہدایات پر لبیک نہیں کہتا اس کا کیا انجام ہوتا ہے؟\nمِّن وَرَآئِهِمۡ جَهَنَّمُۖ وَلَا يُغۡنِي عَنۡهُم مَّا كَسَبُواْ شَيۡـٔٗا وَلَا مَا ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَۖ\nیہاں آگے (قدام) کے لئے،پیچھے (وَرَآء) کی تعبیر استعمال کی گئى ہے، ان کے اعراض وروگردانی کا اعتبار کرتے ہوئے، گویا جہنم ان کے پیچھے ہے۔ (الشوکانی: ۵؍۵)\nآیت کریمہ نےآگے کے لئے (قدام) اورپیچھے کے لئے (وَرَآء) کی تعبیر کیوں استعمال کی ہے؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ١٣\nوہ لوگ جو اللہ تعالىٰ کی نشانیوں سے استدلال کرتے ہیں ان کی آخرى صفت ذکر کرتے ہوئے یہاں “تفکر” کے لفظ کو ترجیح دیا گیا ہے، کیونکہ فکر ایمان، یقین اور علم کا سر چشمہ ہے جن کا ذکر آگے اللہ تعالىٰ کے فرمان: (لآيات للمؤمنين)، (آيات لقوم يوقنون)، (آيات لقوم يعقلون) میں گزر چکا ہے۔ (ابن عاشور: ۲۵؍۳۳۸)\nتفکر -غور وفکر کرنے- کا فائدہ بتایئے؟\nwords\nيَبُثُّوه پھيلاتا هے؛ متفرق كرتا هے.\nوَيلٌهلاكت /تباهي.\nأَفَّاكٍبهت بڑا جھوٹا.\nأَثِيمٍبڑا گنهگار.\nهُزُوًاٹھٹھه و مذاق."],[500,"§الجاثيہ\ndeeds\nاللہ تعالىٰ سے دعا کریں کہ علم کو آپ کی ہدایت اورنیکی کا سبب بنائے، اور اسے آپ کی گمرائی اور بھٹکنے کا سبب نہ بنائے.\nدل میں شریعت کی اتباع کا جذبہ رکھتے ہوئے سنتوں اور واجبات کی پابندی کیجئے، اگرچہ وہ آپ کی خواہش نفس کے خلاف ہوں.\nایک مقالہ یا کوئی خط لکھیئے جس میں اسلامی شریعت کو مضبوطی سے اپنانے پر اس طرح زور دیجئے کہ یہی زندگی گزارنے کا ایک مکمل منہج، اور جامع طریقہ حیات ہے.\nguid\nاپنے دل کو پرکھئے، پس اگر اس میں کسی کے لئے حسد کا جذبہ ہے تو اس کے لئے دعاء خیر فرمایئے، اور استغفار طلب کیجئے.\nکوئی بھی بات جو کتاب وسنت کے مخالف ہو، تو جان لیں کہ وہ اسی ہوائے نفس کی شاخ ہے جس سے اللہ تعالىٰ نے روکا ہے.\nاللہ تعالىٰ نے یہاں خواہش نفس اور عدم علم کے درمیان تعلق کی طرف اشارہ کیا ہے، چنانچہ جو شخص جاہل ہوگا وہ خواہش نفس کی اتباع کے زیادہ قریب ہوگا.\nrefl\nمَنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۖ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ ١٥\n(من عمل صالحا فلنفسه) اللہ کے بندوں میں سے جس نے بھی اللہ کی اطاعت کی، اس کے اوامر واحکام کو مانا، اس کی منع کردہ چیزوں سے دور رہا، تو اس نے یہ نیک عمل اپنے نفس کے لئے کیا، اور اس طرح اس نے اللہ تعالىٰ کےعذاب سے چھٹکارا طلب کیا، گویا اس نے اپنے رب کی کسی اور چیز کے بجائے اسی لئے اطاعت کی، کیونکہ یہ چیز کسی اور کو فائدہ نہیں پہنچائے گی، اور اللہ تعالىٰ کی ذات تو ہر عمل کرنے والے کے عمل سے بے نیاز ہے۔(ومن أساء فعليها) اللہ تعالىٰ کہہ رہا ہے: اور جس نے دنیا میں اللہ تعالىٰ کی نافرمانی، اور اس کے اوامر ونواہی کی مخالفت کرکے اپنے عمل کو خراب کیا، تو اس نے اپنے ہی نفس پر ظلم کیا، اس لئے کہ اس طرح کرکے اس نے اپنے ہی نفس کو ہلاکت میں ڈالا، اور اپنے رب کی ناراضگی مول لی، اور اپنے نفس کے سوا کسی اور کو نقصان نہیں پہنچایا۔ (الطبری: ۲۲؍۶۸)\nاللہ تعالىٰ نے نیک اور برے عمل کو،اس کے کرنے والے کے ساتھ کیوں جوڑ دیا ہے؟\nوَلَقَدۡ ءَاتَيۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَى ٱلۡعَٰلَمِينَ ١٦ وَءَاتَيۡنَٰهُم بَيِّنَٰتٖ مِّنَ ٱلۡأَمۡرِۖ فَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ١٧\nاس میں اس امت کو اس بات سے ڈرایا گیا ہے کہ وہ بنی اسرائیل کا راستہ اپنائے، اور ان کا طور طریقہ اختیار کرے۔ (ابن کثیر: ۴؍۱۵۲)\nیہ دونوں آیتیں بنی اسرائیل کے بارے میں ہیں، تو ہم امت محمدیہ کو ان سے کیا فائدہ اٹھانا چاہیئے؟\nوَفَضَّلۡنَٰهُمۡ عَلَى ٱلۡعَٰلَمِينَ ١٦\nقرآن میں جہاں کہیں بھی بنی اسرائیل کی فضیلت آئی ہے تو وہاں مقصد ان کے گزرے ہوئے حالات کو بیان کرنا ہے، کیونکہ جب قرآن نازل ہوا تو انہوں نے اس کو جھٹلایا اور اس کا انکار کیا، جیسا کہ اللہ تعالىٰ نے ارشاد فرمایا ہے: ﴿فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦ﴾ [البقرة: ٨٩]، یعنی: جب ان کے پاس وہ چیز آئی جسے وہ پہلے سے جان چکے تھے تو انھوں نے اس کا کفر -انکار-کیا، تو کافروں پر اللہ تعالىٰ کی لعنت ہو’’۔ اور یہ چیز معلوم ہے کہ اللہ تعالىٰ نے قرآن میں ان کا فضل جہاں بھی بیان کیا ہے اس سے مقصود ان کا گزرا ہوا زمانہ ہے جس میں وہ فضل وشرف والے تھے، نہ کہ قرآن کے نزول کے وقت۔ (الشنقیطی: ۷؍۱۹۸-۱۹۹)\nبنی اسرائیل کی پوری دنیا پر فضیلت کا مطلب واضح کیجئے؟\nفَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ\nیعنی: آپ صلی اللہ علیہ وسلم سے حسد کرتے ہوئے۔ کہا گیا ہے کہ (بغيا) کا معنى یہ ہے کہ: ان میں سے بعض نے بعض پر زیادتی کی، اپنی برتری و سرداری کا مطالبہ کیا ، اور انبیاء علیہم السلام کو قتل کیا، تو اے محمد صلی اللہ علیہ وسلم اسی طرح آپ کے زمانے کے مشرک بھی ہیں، ان کے پاس -اللہ تعالىٰ کی طرف سے- واضح نشانیاں آئیں، مگر انہوں نے قیادت و سیادت کے چکر میں اس سے اعراض کیا۔ (القرطبی: ۱۹؍۱۵۳)\nوہ کونسی ظلم و زیادتی ہے جو ان سےسرزد ہوئى؟\nثُمَّ جَعَلۡنَٰكَ عَلَىٰ شَرِيعَةٖ مِّنَ ٱلۡأَمۡرِ فَٱتَّبِعۡهَا\nجب اس کا مطلب یہ تھا کہ اللہ تعالىٰ نے بنی اسرائیل کو ایک شریعت عطا کی، اور انہیں اس میں اختلاف کرنے پر دھمکایا، تو ان کو دی گئی دھمکی ہمارے لئے بھی دھمکی ہے، چنانچہ کلام کے سیاق وغیرہ کے تقاضے کے مطابق ہماری دھمکی کی صراحت کردی، اور ساتھ ہی ساتھ ہماری شریعت کی فضیلت و بلندی کی طرف واضح اشارہ بھی کردیا: (ثم جعلناك على شريعة من الأمر...) (البقاعی: ۷؍۱۰۰)\nآیت کریمہ : (ثم جعلناك على شريعة من الأمر) کا اس سے پہلے کی آیتوں سے کیا تعلق ہے؟\nهَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُوقِنُونَ ٢٠\nیہاں اللہ تعالىٰ نے اہل یقین کو اس چیز کے ساتھ خاص کردیا ہے کہ قرآن ان ہی کے لئے بصیرت، ہدایت اور رحمت کا باعث ہے، اس لئے کہ انھوں نے ہی قرآن سے فائدہ اٹھایا ہے، نہ کہ اس کافر نے جس نے قرآن کو جھٹلایا، چنانچہ قرآن اس کے لئے اندھا پن اور غم کا سامان ثابت ہوا۔ (الطبری: ۲۲؍۷۲)\nیہاں اللہ تعالىٰ نے کیوں اہل یقین کو اس چیز کے ساتھ خاص کردیا کہ قرآن ان کے لئے بصیرت، ہدایت اور رحمت کا باعث ہے؟\nأَمۡ حَسِبَ ٱلَّذِينَ ٱجۡتَرَحُواْ ٱلسَّيِّـَٔاتِ أَن نَّجۡعَلَهُمۡ كَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَوَآءٗ مَّحۡيَاهُمۡ وَمَمَاتُهُمۡۚ سَآءَ مَا يَحۡكُمُونَ ٢١\nابراہیم بن اشعث نے فرمایا: میں نے فضیل بن عیاض کو اکثر دیکھا کہ رات کی ابتداء سے لے کر اس کی انتہاء تک یہ اور اس طرح کی آیتیں دہراتے رہتے۔، پھر کہتے: کاش میں جانتا کہ تم کس گروہ میں سے ہو؟ اور اس آیت کو “مبکاۃ العابدين” -یعنی: عبادت گزاروں کو بہت زیادہ رلانے والی- کہا جاتا تھا۔ (القرطبی: ۱۹؍۱۵۷)\nاس آیت کے ساتھ سلف کا کیا رویہ تھا؟\nwords\nلاَ يَرجُونَ أَيَّامَ اللهِوه دشمن پر عذاب آنے كي توقع نهيں كرتے.\nوَالحُكمَفيصله / حكمت.\nلَن يُغنُوا عَنكَوه آپ كو بچا نهيں سكتے.\nبَصَائِرُجس سے لوگ حق بات كو ديكھتے هيں."],[501,"§الجاثيہ\ndeeds\nصرف گزشتہ ہفتے آپ سے جو غلطیاں اور گناہ سرزد ہوئے ہیں انھیں شمار کیجئے.\nیہ دعا کیجئے:(اَللّٰهُمَّ اجْعَلْ فِىْ قَلْبِىْ نُورًا، وفِىْ سَمْعِىْ نُورًا، وفِىْ بَصَرِیْ نُورًا) : اے اللہ! میرے دل میں نور پیدا فرما، میرے کان میں نور اور میری نظر میں نور پیدا کردے.\nیہ دعا کیجئے: (اَللّٰهُمَّ اهْدِنِىْ فِيْمَنْ هَدَيْتَ، وَعَافِنِىْ فِيْمَنْ عَافَيْتَ، وَتَوَلَّنِىْ فِيْمَنْ تَوَلَّيْتَ) : اے اللہ! مجھے ان لوگوں کے ساتھ ہدایت دے جنہیں تو نے ہدایت دی، مجھے عافیت دے ان لوگوں کے ساتھ جنہیں تونے عافیت بخشی اور مجھے اپنا دوست بنا ان لوگوں کے ساتھ جنہیں تونے دوست بنایا.\nguid\nآپ یہ بات جان لیں کہ سب سے بڑی بد نصیبی یہ ہے کہ اللہ تعالىٰ آپ کو علم کے باوجود گمراہ کردے.\nآپ کی ہدایت، خوش بختی، اور کامیابی صرف اللہ تعالىٰ کے ہاتھ میں ہے، لہٰذا اسی سے یہ چیزیں مانگیئے.\nقبل اس کے کہ آپ کا محاسبہ کیا جائے، آپ خود اپنے نفس کا محاسبہ کیجئے.\nrefl\nأَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ٢٣\n(اتخذ إلهه هواه) یعنی: اپنی خواہش نفس کی پیروی کی یہاں تک کہ وہ اس کے معبود کی طرح ہوگیا۔ (ابن جزی: ۲؍۳۲۸)\nخواہش نفس اللہ کے سوا معبود کیسے بن سکتا ہے؟\nأَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ٢٣\nاس آیت میں نفسانی خواہشات کی اتباع کی شدید مذمت ہے۔ ابن عباس رضی اللہ عنہ سے مروی ہے کہ اللہ تعالىٰ نے جب بھی خواہش نفس کا ذکر کیا ہے اس کی مذمت کی ہے۔ اور وہب نے فرمایا: جب تمہیں دو معاملات میں کسی ایک کے زیادہ بہتر ہونے میں شک ہوجائے تو یہ دیکھو کہ دونوں میں کون ساتمہاری خواہش نفس سے دور ہے، اسی کو بجا لاؤ۔ اور سہل تستری نے فرمایا: تمہاری نفسانی خواہش تمہارى بیماری ہے، پس اگر تم نے اس کی مخالفت کی تو وہی تمہاری دوا ہے۔ (الألوسی: ۲۵؍۲۰۹)\nعقلمند آدمی اپنی خواہشات نفس،اور نفس کے ذریعہ معاصى ومنکرات کی چاہت سے کیسے نمٹتا ہے؟\nأَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ٢٣\nیہ آیت اس بات سے ڈرانے میں ایک اصل اور قاعدہ کی طرح ہے کہ مومنوں کو خواہش نفس ان کے اعمال پر آمادہ کرے، اور وہ حق کے دلائل کی پیروی کریں۔ ہاں اگر کسی کو حق محبوب ہو، تو یہ دلیل کی روشنی میں حق کی محبت کا رنگ چڑھنے اور اسے اپنانے کا نتیجہ ہے، جس طرح کوئی مومن نماز باجماعت، تروایح، اور تلاوت قرآن سے محبت کرتا ہے۔ اور حدیث شریف میں ہے: “اے بلال نماز کے ذریعہ ہمیں راحت وسکون پہنچاؤ” یعنی: نماز قائم کرکے۔ اور رہا نفس کو راضی وخوش کرنے کی خاطر پسندیدہ چیز کی اتباع کرنا، بغیر اس کے اچھا یا برا ہونے پر دھیان دیئے ہوئے، تو یہ گمراہی اور اخلاق کے بگاڑ کا سبب ہے۔ (ابن عاشور: ۲۵؍۳۵۹)\nاس آیت کریمہ نے خواہش نفس کی پیروی کے باب میں ایک اہم اصول پیش کیا ہے، وہ کیا ہے؟\nوَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ مَّا كَانَ حُجَّتَهُمۡ إِلَّآ أَن قَالُواْ ٱئۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ ٢٥\nاللہ تعالىٰ نے ان کے باپ دادا کو زندہ کرنے کی ان کی فرمائش کو اس امت کی عزت وتکریم میں ٹھکرا دیا ،اس امت کے نبی محمد صلی اللہ علیہ وسلم کے مقام ومرتبہ کا لحاظ کرتے ہوئے، کیونکہ ثابت شدہ سنت الہی یہ ہے کہ جب مطلوبہ نشانیاں بھیج کر معاملہ بالکل واضح کر دیا جاتا ہے، پھر بھی کوئی ایمان نہیں لاتا ہے تو اللہ تعالىٰ اسے ہلاک وبرباد کر دیتا ہے، یہی اللہ تعالىٰ نے گزشتہ امتوں کے ساتھ کیا ہے۔ (البقاعی: ۷؍۱۰۶)\nاللہ تعالیٰ نے مشرکین کے باپ دادا کو زندہ کرنے کے سلسلے میں مشرکین کا مطالبہ ٹھکرادیا اس میں اس امت کی عزت و تکریم ہے اس کی وضاحت کیجئے؟\nوَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ مَّا كَانَ حُجَّتَهُمۡ إِلَّآ أَن قَالُواْ ٱئۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ ٢٥\nزمخشری نے کہا: اگر آپ یہ کہیں کہ مشرکین کى بات کو دلیل اور حجت سے کیوں تعبیر کیا گیا جبکہ وہ دلیل نہیں ہے؟ تو میں جوابا یہ کہوں گا کہ چونکہ انھوں نے اپنی بات کو ایک دلیل پیش کرنے والے کی طرح پیش کیا، اور اسی سیاق میں اس کو لے کر آئے، اس لئے بطور تہکم ، استہزاء اور تحقیر وتوبیخ کے اسے دلیل اور حجت کا نام دیا گیا۔ یا اس لئے کہ وہ ان کے وہم وگمان اور اندازے کے مطابق دلیل ہے۔ یا یہ سمجھ لیں گویا کہا گیا ہو کہ ان کے پاس کوئی دلیل وحجت نہیں تھی سوائے ایسی دلیل وحجت کے جو فی الحقیقت دلیل وحجت ہےہی نہیں۔ اور مقصود اس بات کی نفی کرنا ہے کہ ان کےپاس کوئی دلیل اور حجت ہے۔ (البقاعی: ۱۹؍۱۶۷)\nاللہ تعالىٰ نے ان کی بات کو دلیل اور حجت کا نام کیوں دیا؟\nوَتَرَىٰ كُلَّ أُمَّةٖ جَاثِيَةٗۚ\nخوف اور گھبراہٹ کے عالم میں اپنے گھٹنوں کے بل ہوں گے، اور اللہ جل جلالہ کے حکم کا انتظار کر رہے ہوں گے۔ (السعدی: ۷۷۸)\nقیامت کے دن امتیں گھٹنوں کے بل کیوں ہوں گی؟\nفَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُدۡخِلُهُمۡ رَبُّهُمۡ فِي رَحۡمَتِهِۦۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡمُبِينُ ٣٠\nتفصیل بیان کرتے وقت مومنوں کے احوال سے گفتگو شروع کی گئی ہے، جبکہ سیاق باطل پرستوں کے بارے میں گفتگو کا تھا، جیسا کہ اللہ تعالىٰ کے اس قول:(يومئذ يخسر المبطلون) میں ہے، اس سے مقصود مومنوں کی شان بڑھانا، ان کو خوش کرنے والی نیز باطل پرستوں کو تکلیف پہنچانے والی چیز کو جلدی ذکر کرنا ہے۔ (ابن عاشور: ۲۵؍۳۷۱)\nاللہ تعالىٰ مومنوں کی مختلف طریقوں سے عزت وتکریم کرتا ہے، اس آیت کی روشنی میں ان میں سے ایک ذکر کیجئے؟\nwords\nوَخَتَمَاور مهر لگادي.\nغِشَاوَةًپردے.\nلاَ رَيبَ فِيهِاس ميں كوئي شك نهيں.\nإِن نَظُنُّ إِلاَّ ظَنًّاهم صرف وهم كي بنياد پر اس كے وقوع كي توقع ركھتے تھے."],[502,"§الجاثيہ ، الأحقاف\ndeeds\nپڑھئے: (اَللّٰهُمَّ أَعِنِّىْ عَلٰى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ) (اے الله! اپنے ذكر وشكر اور بہترین عبادت پر میرى مدد فرما).\nبوقت صبح سو مرتبہ اور بوقت شام سو مرتبہ (سُبْحٰنَ اللّٰهِ وَبِحَمْدِهٖ ) پڑھئے.\nآج اپنى نمازوں میں طویل ركوع كیجئے اور اس میں عظمت والى صفتوں كےساتھ الله كى تسبیح وپاكى بیان كیجئے.\nguid\nلمبى امیدیں اور دنیا كے فریب میں آجانا عذاب الٰہى كے نزول كا ایك سبب ہے.\nیاد رکھئے کہ جوکچھ آپ نے چھپارکھا ہے وہ قیامت کے دن ظاہر ہوہی جائے گا.\nٹھٹھا اور مذاق اڑانے سے اجتناب كیجئے، خصوصى طورپر دینى شعائر كا مذاق اڑانے سے بچئے ، كیونكہ اس كا انجام برا اور بھیانك ہے.\nrefl\nوَغَرَّتۡكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ\nدنیا نے تمہیں اپنى جھوٹى شان وشوكت اور رنگینیوں ورعنائیوں سے فریب دیدیا ہے اس لئے تم نے یقین کرلیا کہ دنیا ہی سب کچھ ہے اور بروز قیامت دوباره نہیں اٹھایا جائےگا ۔ (القرطبى: ۱۹؍۱۷۳)\nدنیا نے لوگوں كو كیسے دھوكہ دے ركھا ہے؟\nفَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ ٣٦\nلفظ جلالہ (رَبِّ)كى تكرار میں لطیف اشاره یہ ہے كہ رب كا اپنى مخلوق كى تربیت وحفاظت مخلوق كى حالتوں كےاعتبار سے جدا جدا ہے۔ ایك ہى مخلوق كے بعض اجزاء كى حفاظت اسى كے دوسرے اجزاء کی حفاظت سے مختلف ہوتى ہے۔ اور اسى كى كل حفاظت اس كے ہرجزء كے جزوى حفاظت سے الگ ہوتى ہے حالانكہ یہ تمام مختلف النوع حفاظتیں الله كى قدرتِ كاملہ كے اعتبار سے یكساں درجہ میں ہیں۔ (البقاعی: ۱۸؍۱۱۶)\nلفظ جلالہ (رَبِّ) مكرر كیوں آیا ہے؟\nفَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ ٣٦ وَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ\nعبادت كى بنیاد دو ركنوں پرہے: ایك الله سے محبت اور دوسرا اللہ کے سامنے اظہار تذلل۔ اور یہ دونوں چیزیں الله تعالىٰ كى حمد ، اور اس ذات كى عظمت وجلال كى معرفت وعلم سے پیدا ہوتی ہیں۔ (السعدى: ۷۷۹)\nعبادت کے ارکان کیا کیا ہیں، اور کس چیز سے پیدا ہوتے ہیں؟\nوَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٣٧\nابو ہریره(رضی اللہ عنہ)سےروایت ہے كہ رسول الله صلی اللہ علیہ وسلم نے فرمایا: الله تعالىٰ فرماتا ہے : بڑائى وكبریائى میرى چادر ہے، اور عظمت وجلال میرا پہناوا ہے، لہٰذا جو بھى مجھ سے اسے اپنے لئےکھینچے گا، میں اسے جہنم میں ڈال دوں گا۔ (الشوكانى : ۵؍۱۲)\nحدیث سے الله تعالىٰ كى صفت : كبریائى وبڑائى كى وضاحت كیجئے.\nتَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ٢ مَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۚ\nجب الله تعالىٰ نے نزولِ قرآن كا ذكر فرمایا جو امر ونہى پر مشتمل ہے، تو آسمان وزمین كى تخلیق كا بھى تذكره فرمایا، یوں خلق وامر كو الله تعالىٰ نے جمع كردیا: ﴿أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُ﴾[الاعراف: ۵۴] “الله ہى كیلئے خاص ہے خالق ہونا اورحاكم ہونا”۔ (السعدى: ۷۷۹)\nنزول قرآن كے ذكر كے بعد تخلیق آسمان وزمین اور ان کے درمیان کی چیزوں كا تذكره الله نے كیوں فرمایا؟\nوَمَنۡ أَضَلُّ مِمَّن يَدۡعُواْ مِن دُونِ ٱللَّهِ مَن لَّا يَسۡتَجِيبُ لَهُۥٓ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ وَهُمۡ عَن دُعَآئِهِمۡ غَٰفِلُونَ ٥\nآیت كا معنى یہ ہے كہ جو شخص ایسے معبود كو پكارتا ہےجو اس كى پكار كو نہیں سنتا ، تو اس سے بڑا گمراه كوئى نہیں ہے، اور وه بت ہیں جو نہ سنتےہیں اور نہ ہى عقل ركھتےہیں ، لہذا وه غافل ہیں ، دعاؤں كو قبول نہیں كرسكتے اس لئے كہ وه سنتےہى نہیں ہیں ۔(ابن جزى: ۲؍۳۳۱)\nجو معبود سنتا نہیں ہے ، اسے پكارنا جہالت وگمراہى ہى ہے، آیت كى روشنى میں اس كى وضاحت كیجئے.\nوَهُمۡ عَن دُعَآئِهِمۡ غَٰفِلُونَ ٥\nبتوں كو غافل كہہ كر انہیں ایسے انسانوں سے تشبیہ دى گئى ہے جو كہى ہوئى باتوں كو بھول جاتےہیں اس لئے كہ بت بھى كہى ہوئى باتوں كو سمجھنے سے قاصر ہے اور غافل انسان بھى، اور یہ الله كى طرف سے مشركوں كیلئے ایك پھٹكار ہے جو عبادت كیلئے فاسد رائے واختیار قبیح كى بنا پر ایسے معبود كو پكارتےہیں جو باتوں كو سمجھ نہیں سكتے۔ (الطبرى: ۲۲؍۹۵)\nمشركوں كے معبود كو غفلت سے متصف كیوں كیا گیا ہے؟ اور اس كا مفہوم كیا ہے؟\nwords\nوَحَاقَ بِهِمان پر نازل هوا.\nنَنسَاكُمهم آپ كو عذاب ميں چھوڑ ديتے هيں.\nوَمَأوَاكُمُتمهاري منزل / تمهارا ٹھكانا.\nوَغَرَّتكُمُاور تمهيں دھوكا ديا.\nوَلاَ هُم يُستَعتَبُونَوه تم سے اپنے رب كو توبه اور اطاعت سے راضي كرنے كامطالبه نهيں كرتے.\nلَهُم شِركٌزمين و آسمان كي تخليق ميں الله كے ساتھ شريك / حصه دار."],[503,"§الأحقاف\ndeeds\nمعاشرے میں موجود بدعتوں پر نظر ركھئے، اورآپ سے وابستہ كچھ لوگوں كو انہیں ترک كرنے كى نصیحت كیجئے.\nبعض خیر وبھلائى كے كاموں كو ذہن میں ركھئے اور آج ہی اسے كركے غیروں پر سبقت لےجائیے.\n(رَبِّىَ اللّٰه) (کہیں : میرا رب اللہ ہے)اور تمام عبادتوں كو بہتر طریقوں (آج ہی سے)سے اداكرنے كى كوشش كیجئے.\nguid\nرسول صرف وحى كى اتباع كرتےہیں، تو ہمیں بھى بدرجۂ اولىٰ ایسا ہى كرنا چاہئے.\nعجب وغرور ہدایت سے محرومى كا ایك سبب ہے.\nدین پر استقامت كى فضیلت واہمیت.\nrefl\nكَفَىٰ بِهِۦ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ٨\nآخر میں آپ صلی اللہ علیہ وسلم كو آپ صلی اللہ علیہ وسلم پر لگائےگئے الزام وافتراء پر عفو ودرگزر سے كام لینے كى ترغیب دى گئى ہے۔ بلكہ ان كے ساتھ احسان وبھلائى كا معاملہ كرنے پر ابھارا گیا ہے ، اور اس میں كافروں كیلئے تو بہ كى ترغیب بھى ہے۔ (البقاعى : ۱۸؍۱۳۲)\nآیت كے اخیر میں اللہ سبحانہ و تعالیٰ کی دو صفتوں (الغفور ) و (الرحيم) كا ذكر ہے، ان میں كن باتوں كى طرف اشاره ہے؟\nكَفَىٰ بِهِۦ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ٨\nآیت میں انہیں تاكیدى وعید اور سختى سے ڈرایا دھمكایا گیا ہے ، اور الله كا فرمان: (وهو الغفور الرحيم) میں انہیں توبہ وانابت كى ترغیب دى گئى ہے، یعنى گزشتہ تمام كرتوتوں كے باوجود اگر تم الله كى طرف لوٹ آئے اور توبہ كرلی، تو الله تمہارى توبہ قبول كرےگا، تم كو معاف كرےگا، بخش دےگا اور تم پر ر حم كرےگا۔ (ابن كثیر: ۴؍۱۵۷)\nقرآن مجید میں الله تعالىٰ ہمیشہ ترغیب وترہیب كو یكجا بیان كرتاہے، آیت كى روشنى میں اس كى وضاحت كیجئے.\nقُلۡ مَا كُنتُ بِدۡعٗا مِّنَ ٱلرُّسُلِ\nحرف جر “مِنْ” آغاز وابتداء كیلئے آتا ہے، مطلب یہ ہے كہ میں رسولوں میں پہلا یا انوكھا پیغمبر نہیں ہوں ، بلکہ جس طرح تم نے گزرے ہوئے تمام پیغمبروں کے بارے میں سنا ہے کہ انہوں نے پیغامِ الٰہی کو لوگوں تک پہنچایا تو میں اسی طرح ہوں تو پھر انہیں میری دعوت پر کیوں تعجب ہورہا ہے۔ یہ آیت ہمارےزمانےكے ان عیسائیوں پر رد كرنے كیلئے مناسب ہے جنہوں نے آپ صلی اللہ علیہ وسلم كى نبوت پر كچھ ایسے الزام لگائےہیں جن كامقصد صرف اپنے عیسائى بھائیوں كو گمراه كرنا اور دھوكہ میں ركھنا ہے۔ اس لئے كہ طعن وتشنیع كرنے والے اپنى عوام كے تعلق اتنے بھى بیوقوف نہیں ہیں كہ ان پر ان لوگوں كا بہتان مخفى ره جائے۔ (ابن عاشور: ۲۶؍۱۷)\nاس آیت كےذریعہ آپ عیسائیوں پر كیسے رد كریں گے؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ لَوۡ كَانَ خَيۡرٗا مَّا سَبَقُونَآ إِلَيۡهِۚ\nہروه قول وفعل جو صحابہ كرام (رضی اللہ عنہم)سے ثابت نہیں ہے اہل سنت وجماعت كے نزدیك بدعت ہے، اس لئے كہ وه اگر نیكى كا كام ہوتا تو صحابہ اس پر ہم سےپہلے عمل كرچكے ہوتے كیوں كہ انہوں نے عبادت وبھلائى كے ہر كام كو آگے بڑھ كر انجام دیا ہے۔ (ابن كثیر: ۴؍۱۵۹)\nصحابہ كرام كےتعلق سے اہل شرك اور اہل سنت وجماعت كے موقف میں كیا فرق ہے؟\nإِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١٣\nیہ وه لوگ ہیں جنہوں نے خلاصۂ علم: توحید اور غایت عمل: استقامت دونوں كو اپنے اندر جمع كر لیا ہے۔ (الألوسى: ۲۵؍۲۴۰)\nارشاد بارى : (قالوا ربنا الله ثم استقاموا)كا مقصود كیا ہے ؟\nإِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١٣\nاس آیت میں اشاره یہ ہے كہ الله كا خوف وہیبت دلوں میں باقى رہے گى اگر انسان اس كے عظمت وجلال ، قہر وغلبہ اور كبریائى وكمال كا تصور كرے، نیز ان صفتوں كو ذہن میں حاضر ركھنے سے خود انسان كےاندر خضوع وتذلیل ، عاجزى وانكسارى ، اور سكون واطمینان اور وقار پیدا ہوگا جو اس كے مقام ومرتبہ اور رفعت وعظمت كو بڑھائےگا۔ بہرحال یہاں اس خوف كى نفى ہے جو انسان كو قلق واضطراب میں مبتلا كردے۔ (البقاعى: ۱۸؍۱۴۴)\nیہاں كس طرح كے خوف كى نفى كى گئى ہے؟\nأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ١٤\nبندے كےاندر تقصیر وكوتاہى ہمیشہ پائى جاتى ہے،وه ہمہ وقت الله كے عفو ودرگزر اورمغفرت كے محتاج ہوتےہیں، كوئى بھى اپنے اعمال كى وجہ سے جنت میں نہیں جائےگا، ہر شخص گنہگار ہے اور الله كى بخشش كا محتاج ہے ﴿وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٍ﴾ [فاطر: ۴۵] “اور اگر الله تعالىٰ لوگوں پر ان كے اعمال كےسبب دار وگیر فرمانے لگتا تو روئے زمین پر ایك جاندار كو نہ چھوڑتا” اور حدیث : “لَنْ يَّدْخُلَ اَحَدٌ مِّنْكُمُ الْجَنَّةَ بِعَمَلِهٖ” كوئى جنت میں اپنے عمل كےسبب ہر گز نہ جائےگا۔ اور آیت (جزاء بما كانوا يعملون) میں كوئى ٹكراؤ نہیں ہے۔ عمل جزاء كا سبب ہے لیكن عمل اور جزاء میں كوئى تقابل نہیں ہے، اس لئے گمراه ہے وه شخص جو یہ گمان ركھتاہے كہ اس نے اپنا حق ادا كردیا ہے اور اللہ تعالیٰ سے عفو ودر گزر اورمغفرت كا محتاج نہیں ہے۔ (ابن تیمیہ : ۵؍۵۴۹)\nحدیث “لَنْ يَّدْخُلَ اَحَدٌ مِّنْكُمُ الْجَنَّةَ بِعَمَلِهٖ” اور آیت (جزاء بما كانوا يعملون)میں تطبیق كیسے دیں گے؟\nwords\nافتَرَاهُاسے گھڑ ليا هے.\nتُفِيضُونَ فِيهِتم قرآن كے متعلق كهتے هو.\nبِدعًا مِنَ الرُّسُلِخلق الله كي طرف الله كا پهلا رسول.\nأَرَأَيتُممجھے بتاؤ تو سهي.\nوَشَهِدَ شَاهِدٌگواه نے گواهي دي۔ جيسے حضرت عبدالله بن سلام رضي الله عنه.\nإِفكٌ قَدِيمٌپرانے لوگوں سے منقول جھوٹ.\nاستَقَامُواوه ايمان اور اطاعت گزاري پر ثابت قدم رهے."],[504,"§الأحقاف\ndeeds\nاپنے والدین کی انسیت وخوشی کے لئے آج ایک وقت خاص کر لیجئے اور انہیں معمولی ہی سہی کوئی تحفہ پیش کیجئے.\nتصور کیجئے کہ آپ نے دن بھر کے لئے پانچ کلو کی کوئی چیز اٹھا رکھی ہے پھر اپنی ماں کی تکلیفوں ، مشقتوں اور دشواریوں کا اندازہ لگائیے جب آپ رحم مادر میں تھے.\nآج اپنے سجدوں میں اس دعا کو پڑھئے.\nguid\nآپ کی رعایت وتربیت میں آپ کی والدہ نے حمل ، ولادت ، رضاعت ، غذا ونظافت اور مرض و ہدایت کے مختلف ایام کی تکلیفوں کو جھیلا ہے تو کیا آپ ان کا حق پورا پورا ادا کر پائیں گے ؟\nجو اپنے والدین کی نافرمانی کرے ،معمولی ایذا رسانی کے ذریعہ ہی سہی ، تو وہ اس آیت کی وعید میں داخل ہو سکتا ہے.\nناز ونعم کی کثرت وعیش کوشی کبر وغفلت کو جنم دیتی ہے.\nrefl\nوَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ\nاس آیت میں اشارہ یہ ہے کہ ماں کا حق باپ کے حق پر مقدم ہے ، وجہ یہ ہے کہ ماں حمل ، زچگی اور مدت رضاعت کی تمام مشقتوں اور تھکانوں کو تن تنہا جھیلتی ہے ، اس میں باپ کی شرکت نہیں ہوتی ۔ (الشوکانی: ۵؍۱۸)\nآیت میں والدین کے ساتھ حسن سلوک کا حکم مقرر ہے لیکن اس میں اشارہ یہ ہے کہ ماں کا حق باپ کے حق پرمقدم ہے ، اس کی وضاحت کیجئے.\nحَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ ١٥\nاس آیت میں چالیس سال کی عمر پا چکے مسلمان کے لئے رہنمائی یہ ہے کہ وہ پختہ دل سے توبہ کی تجدید کرے اور از سرِ نو اللہ کی طرف پلٹے اور اس پر جم جائے۔ (ابن کثیر: ۴؍۱۶)\nچالیس سال کی عمر والوں کے لئےآیت میں کیا ہدایت ہے؟\nحَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ\nآیت میں پختگی کی عمر کی تخصیص اس لئے کی گئی ہے کہ اس عمر میں مرد روزی روٹی کے لئے بہت زیادہ تگ ودو کرتے ہیں کیوں کہ ان کے کندھوں پر اہل وعیال کی ذمہ داری رہتی ہے اور خواتین بھی اس عمر میں زیادہ مصروف رہتی ہیں ، اس لئے کہ شوہر ، گھر اور بچوں کی ذمہ داریاں سنبھالتی ہیں، چنانچہ پھر وہ وہم و گمان کے ایسے مقام پر نظر آنے لگ جاتے ہیں جہاں ایسا محسوس ہوتا ہے کہ کہیں یہ مصروفیات انہیں اپنے والدین کی دیکھ ریکھ اور ان کے ساتھ حسن سلوک سے برگشتہ نہ کردے، لہٰذا انہیں متنبہ کیاگیا ہے کہ (عمر جو بھی ہو، اور مصروفیات جیسی بھی ہو) اپنے والدین کے ساتھ حسن سلوک میں کوتاہی نہ کریں۔ (ابن عاشور: ۲۶؍۳۲)\nآیت میں والدین کے ساتھ حسن سلوک کے لئے پختگی کی عمر کی تخصیص کیوں کی گئی ہے؟\nأَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ\nوالدین کو نعمتوں سے نوازاجانا ان کی اولاد کو ان نعمتوں سے نوازاجانا ہے، چونکہ ان نعمتوں اور ان کے اسباب و آثار کا اولاد تک پہنچنا لازمی امر ہے خاص طور پر دین کی نعمت، کیونکہ علم و عمل کے ذریعے سے والدین کا نیک ہونا اولاد کے نیک ہونے کا سب سے بڑا سبب ہے (السعدی: ۷۸۱)\nوالدین کو ملنےوالی نعمتوں پر اولاد کیوں شکر بجا لائے؟\nوَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ فِي حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا\nمومن اپنی ساری دنیاوی نعمتوں ولذتوں کو دنیا ہی میں فنا نہیں کرتا بلکہ اپنی بعض نعمتوں وپاکیزہ چیزوں کو آخرت کے لئے چھوڑدیتا ہے لیکن کافر دنیاوی تمام لذتوں سے سرشار ہونے کی حرص رکھتا ہے ، اس لئے کہ وہ آخرت پر ایمان نہیں رکھتا۔ (ابن القیم: ۲؍۴۵۰)\nدنیاوی لذتوں کے تعلق سے مومن وکافر کے موقف میں کیا فرق ہے ؟\nوَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ فِي حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا\nآیت: (يعرض الذين كفروا على النار) کا تعلق کافروں سے ہے ، اس کے باوجود اس میں متقی وپرہیزگار لوگوں کے لئے عبرت وموعظت کا پہلو ہے اور یہی وجہ ہے کہ جب حضرت جابر بن عبد اللہ(رضی اللہ عنہ) نے گوشت خریدا تو حضرت عمر (رضی اللہ عنہ) نے ان سے کہا : کیا تو ڈرتا نہیں کہ تیرا شمار اس آیت کے مصداق لوگوں میں ہو جائے؟ (ابن جزی: ۲؍۳۳۵)\nکافروں کے بارے میں اتری ہوئی آیتوں سے کیا مسلمان نصیحت حاصل کر سکتا ہے ؟ اور کیسے؟\nفَٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَسۡتَكۡبِرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ ٢٠\nتکبر سے مراد ایمان سے کنارہ کشی اور فسق سے مراد اعضاء و جوارح سے سرزد ہونے والے گناہ ہیں ، آیت میں دل کے گناہ کو اعضاء وجوارح کے گناہ پر مقدم کیا گیا ہے چونکہ اعضاء وجوارح کے اعمال دل کی موافقت کے بعد سرزد ہوتے ہیں۔(الألوسى: ۲۵؍۲۵۰)\nآیت میں دل کا گناہ اعضاء وجوارح کے گناہ پر مقدم ہے۔ اس کی وضاحت کیجئے نیز یہ بتائیے کہ دونوں میں سب سے زیادہ خطرناک کون ہے؟\nwords\nوَفِصَالُهُاور اس كا دودھ چھڑانا.\nأَوزِعنِيمجھے الهام كردے.\nأُفٍّ لَكُمَاتم دونوں كے ليے افسوس هے/ برائي هے.\nعَذَابَ الهُونِذلت اور رسوائي كا عذاب."],[505,"§الأحقاف\ndeeds\nآندھی اور بارش کی ماثور دعا کو یاد کر لیجئے اور بوقت آندھی وبارش اسے پڑھئے : (اَللّٰهُمَّ اِنِّيْ اَسْئَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيْهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهٖ، وَاَعُوْذُبِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيْهَا، وَشَرِّ مَا اُرْسِلَتْ بِهٖ) اے اللہ میں تجھ سے اس ہوا کی بھلائی اور اس میں چھپی ہوئی بھلائی اور جس بھلائی کے ساتھ وہ بھیجی گئی ہے ، کا سوال کرتا ہوں ، اور تیری پناہ میں آتا ہوں اس ہوا کی برائی سے اوراس میں چھپی ہوئی برائی سے اور اس چیز کی برائی سے جس کے ساتھ وہ بھیجی گئی ہے.\nتین نیکیاں کرلیجئے، ایک کان سے متعلق، دوسری آنکھ سے متعلق، تیسری دل سے متعلق.\nپچھلی امتوں کی بچی کھچی چند تصویروں کو دیکھئے اور متأثر کرنے والی عبرتوں کو نوٹ کیجئے.\nguid\nپیغمبروں کے واقعات میں آپ صلی اللہ علیہ وسلم اور آپ کے متبعین کے لئے تسکین وتسلی کا سامان ہے.\nقوم عاد اپنی نادانی وتکبر کی بنا پر ان بادلوں سے خوش ہوئے جن میں ان کی ہلاکت مضمر تھی.\nجب عذاب الٰہی نازل ہو جاتا ہے تو علمی ثقافتی اور تعمیراتی ترقیاں فائدہ نہیں پہنچاتیں.\nrefl\n۞وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ\nمثالوں اور گزری امتوں کے واقعات بیان کرنے سے بعض چیزوں کی خوبی وقباحت معلوم ہوتی ہے، لہذا اللہ نے اپنے رسول سے فرمایا: (واذكر أخا عاد) (الألوسى: ۲۵؍۲۵۱)\nقصۂ عاد کی یاددہانی سے کیا فائدہ ہے؟\nقَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ٢٣\n(تجهلون ) پر اکتفا نہ کرکے (قومًا )کا لفظ بھی لایا گیا ہےیہ بتانے کے لئے کہ جہالت اس قوم میں اس قدر گھر کر گئی ہے کہ وہ اس قوم کی بنیادی پہچان بن گئی ہے، نیز لفظ جہالت یہ بتانے کے لئے بھی لایا گیا ہے کہ مرض جہالت پورے قبیلے کو محیط ہے یہ معاملہ ایسا ہی ہے جیسا کہ لوط نے اپنی قوم سے کہا تھا: ﴿أَلَيۡسَ مِنكُمۡ رَجُلٌ رَّشِيدٌ﴾ [هود: ٧٨] کیا تم میں ایک بھی بھلا آدمی نہیں ہے۔(ابن عاشور: ۲۶؍۴۸)\nلفظ “قوم” کا ذکر آیتِ کریمہ میں کس معنى کو بتانے کے لئے ہے؟\nفَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ ٢٤\nصحیح مسلم کی روایت ہے کہ عائشہ(رضی اللہ عنہا) فرماتی ہیں کہ جب آندھی آتی تو رسول اللہ صلی اللہ علیہ وسلم یہ دعا پڑھتے تھے : «اللهم إني أسألك خيرها، وخير ما فيها، وخير ما أرسلت به، وأعوذ بك من شرها، وشر ما فيها، وشر ما أرسلت به»، (اے اللہ میں تجھ سے اس ہوا کی بھلائی اور اس میں چھپی ہوئی بھلائی اور جس بھلائی کے ساتھ وہ بھیجی گئی ہے ، کا سوال کرتا ہوں ، اور تیری پناہ میں آتا ہوں اس ہوا کی برائی سے اوراس میں چھپی ہوئی برائی سے اور اس چیز کی برائی سے جس کے ساتھ وہ بھیجی گئی ہے) اور جب آسمان پر بادل چھا جاتا تو آپ کا رنگ بدل جاتا ، اور آپ کبھی باہر نکلتے ، کبھی اندر جاتے ،کبھی آگے بڑھتے اور کبھی پیچھے مڑ جاتے ، لیکن جب بارش ہوتی تو آپ خوش ہوجاتے تھے میں نے آپ سے اس بابت پوچھا تو فرمایا: پتہ نہیں ، شاید ایسا ہو جائے جیسا قومِ عاد نے کہا تھا : (هذا عارض ممطرنا)». )۔(الألوسى: ۲۵؍۲۵۶)\nآندھی کے وقت یا جب بدلی چھانے لگے تو کونسی مستحب دعا پڑھنی چاہئے؟\nوَلَقَدۡ مَكَّنَّٰهُمۡ فِيمَآ إِن مَّكَّنَّٰكُمۡ فِيهِ\nیعنی؛ اے لوگو! قوم عاد کو ہم نے وہی قوت وشوکت عطا کی تھی جو تمہیں عطا کی ہے ، اس لئے تم یہ نہ سمجھو کہ جو تمہیں عطا ہوا ہے وہ تمہارے ساتھ خاص ہے اور اللہ کے عذاب کو تم سے ٹال سکے گا بلکہ دوسری قومیں قدرت وتمکن میں تم سے زیادہ عظیم تھیں ، لیکن ان کے مال ، اولاد اور فوج ان کو اللہ کے عذاب سے ذرہ برابر بھی بچا نہ سکے۔(السعدی: ۷۸۳)\nاس امر کی وضاحت کیجئے کہ جب اللہ تعالىٰ کسی قوم پر عذاب کا ارادہ کرتا ہے تو اس کی مادی طاقت وقوت کچھ بھی فائدہ نہیں پہنچا سکتی.\nوَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ\nآیت ہذا کا فائدہ یہ ہے کہ عناد کے علاوہ ان کے یہاں کسی اور چیز کی کمی نہیں تھی جو راہ حق کی تلاش میں رکاوٹ بنتی ، قریش مکہ سے اشاروں میں کہا جا رہا ہے کہ تم نے اپنے آپ کو کان ، آنکھ اور عقل وخرد کی صلاحیتوں سے محروم رکھا ، اور یہی عمل پچھلی قوموں نے بھی کیا ہے۔(ابن عاشور: ۲۶؍۵۳)\nارشاد باری: (وجعلنا لهم سمعًا وأبصارًا وأفئدة) کا فائدہ بتائیے.\nوَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ بِـَٔايَٰتِ ٱللَّهِ\nیہ اور اس معنی کی آیتوں سے سمجھ میں آتا ہے کہ کان ، آنکھ اور دل کی صلاحیتوں سے اللہ کی نشانیوں کے منکر فائدہ نہیں اٹھا سکتے ہیں ، یہاں سے یہ بات بھی عیاں ہو جاتی ہے کہ عقل جو مدارِ تکلیف وبندگی ہے صرف اس کی وجہ سے نفع بخش ایمان حاصل نہ ہوگا اور نہ اللہ کے عقاب سے بچاؤ کی تدبیریں معلوم ہوں گی۔ (ابن تیمیہ: ۵؍۵۵۰)\nہدایت صرف عقل کی بنیاد پر نہیں ملتی بلکہ یہ الہی انعام واحسان ہے اس کی وضاحت کیجئے.\nفَلَوۡلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ قُرۡبَانًا ءَالِهَةَۖ بَلۡ ضَلُّواْ عَنۡهُمۡۚ\nیعنی بزعم خویش شفاعت کی خاطر جن معبودوں کو وہ تقرب کا ذریعہ سمجھ کر یوں کہتے ہیں کہ یہ اللہ کے پاس ہمارے سفارشی ہیں انہوں نے ان کی مدد کیوں نہ کی اور ہلاکت سے انہیں کیوں نہ بچا پائے ؟ (الشوکانی: ۵؍۲۴)\nاللہ کے علاوہ جس کی قربت حاصل کی جاتی ہے وہ دنیا وآخرت دونوں جگہ ضعیف ہوتے ہیں ، آیت کی روشنی میں اسکا جواب دیجئے.\nwords\nبِالأَحقَافِجنوب جزيره عرب ميں ايك جگه كا نام.\nلِتَأفِكَنَاتا كه آپ هميں موڑ ديں.\nعَارِضًاآسمان ميں پھيلے هوئے بادل.\nمَكَّنَّاهُمهم نے ان كو قدرت دي؛ او ران كے ليے وسعت دي.\nوَحَاقَاور آن گھيرا.\nقُربَانًاوه اس سے الله تعاليٰ كي قربت حاصل كرتے."],[506,"§الأحقاف\ndeeds\nکوئی عبادت جس کی نصیحت کسی داعی یا خیر خواہ نے کی ہو اس کو یاد کیجئے اور نافذ کیجئے.\nتنہائی میں بآواز بلند قرآن مجید کی تلاوت کیجئے ممکن ہے فرشتے وجنات اسے سنیں اور آپ کے اجر وثواب میں اضافہ ہو جائے.\nقرآن مجید کی ایک آیت کو سنئے اور اسی پر عمل کیجئے ، شاید آپ کا شمار اہل قرآن میں ہو جائے.\nguid\nمومن بندہ دوسروں کی تعلیم ونفع رسانی کا غم لئے پھرتا ہے.\nوہ ذات جس نے آسمان وزمین کو پیدا کیا ، انسان کو مرنے کے بعد زندہ کرنے پر قدرت رکھتی ہے.\nصبر پیغمبرانہ اخلاق ہے اور دنیا وآخرت میں کامیابی کا ذریعہ ہے.\nrefl\nوَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرٗا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ ٢٩\nیعنی جنات نے کہا قرآن کو خاموشی سے بغور سنو ، قرآن کے ساتھ ان کا یہ ادب تھا(ولوا إلى قومهم منذرين) وہ اپنی قوم کو دھمکانے اور آگاہ کرنے کے لئے واپس ان کی طرف چلے، اور انہیں رسول اللہ (صلی اللہ علیہ وسلم) کی جانب سے ہرسنی ہوئی باتوں پر آگاہ کیا، جیسے اللہ عزوجل کا فرمان ہے: ﴿لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ﴾ (التوبۃ:۱۲۲) یعنی وہ دین کی سمجھ حاصل کریں، اور جب واپس اپنی قوم کے پاس پہنچیں تو انہیں بھی ہوشیار کریں، بہت ممکن ہے کہ وہ بچاؤ اختیار کرلیں، اس آیت سے استدلال کیاگیا ہے کہ جنات میں اللہ کی باتوں کو پہنچانے والے اور ڈرسنانے والے ہیں لیکن ان میں رسول نہیں بنائے گئے ہیں، یہ بات بلاشبہ ثابت ہے کہ جنات میں پیغمبر نہیں ہیں۔(ابن کثیر: ۴؍۱۷۲)\nجنوں نے قرآن سنتے وقت کون سا ادب اختیار کیا تھا؟اور کیا جنوں میں سے کوئی رسول ہے؟\nقَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ\nانہوں نے عیسیٰ (علیہ السلام) کا ذکر اس لئے چھوڑدیا کہ ان پر انجیل کا نزول ہوا تھاجس میں زیادہ تر وعظ اور دل کو نرم کرنے کے بیانات تھے، حرام و حلال کے مسائل بہت کم تھے، یہ کتاب دراصل تورات کو پورا کرنے والی تھی، پس اصل چیز تورات ہی رہی، اسی لئے ان مسلم جنات نے (أنزل من بعد موسى) کہا اور اسی کا ذکر کیا۔ اور اسی بات کو پیش نظر رکھ کر ورقہ بن نوفل نے جس وقت نبی کریم (صلی اللہ علیہ وسلم) کی زبانی حضرت جبریل(علیہ السلام) کے اول دفعہ آنے کا حال سنا تو کہا تھا کہ واہ واہ یہ تووہ مبارک رازدار ہیں جو موسیٰ (علیہ السلام) کے پاس آیاکرتے تھے۔ (ابن کثیر: ۴؍۱۷۳)\nجنوں نے (أنزل من بعد موسى) نہ کہہ کر (أنزل من بعد عيسى) کیوں کہا؟\nمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِيقٖ مُّسۡتَقِيمٖ ٣٠ يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ بِهِۦ\nمسلم جنات نے قرآن کی تعریف وتوصیف اور اس کا مقام ومرتبہ بیان کیا اور پھر اس پرایمان لانے کی دعوت دی ۔ (السعدی: ۷۸۳)\nجن کے مرتب کلام میں ایک اہم دعوتی فائدہ ہے اس کی وضاحت کیجئے.\nفَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۢ بَلَٰغٞۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ ٣٥\nدین میں قابل ستائش عزم وہ ہے جو تزکیہء نفس اور امت کو نیک وصالح بنانے پر مشتمل ہو اور جس کی بنیاد مصائب وشدائد پر صبر کرنا ہے اور جس کا باعث ومحرک تقوىٰ وخشیت الہی ہے اور جس کی غذا محاسبۂ نفس ہے اور اللہ تعالىٰ کے سخت مراقبہ پر ہےتاکہ مومن بندہ اپنے نفس کے محاسبہ میں سستی اور کاہلی سے کام نہ لے۔ارشاد باری تعالىٰ ہے: ﴿وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ﴾ [آل عمران: ۱۸۶] اور اگر تم صبر کر لو اورپرہیزگاری اختیار کرو تو یقینا یہ بہت بڑی ہمت کا کام ہے ۔(ابن عاشور: ۲۶؍۶۷)\nعزم محمود کی بنیادیں کیا کیا ہیں؟\nفَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ\nاولوالعزم پیغمبر نوح ، ابراہیم ، موسىٰ ، عیسىٰ ،اور محمد صلی اللہ علیہ وسلم ہیں ، آپ صلی اللہ علیہ وسلم اس کڑی کے پانچویں پیغمبر ہیں اور آپ صلی اللہ علیہ وسلم سے پہلے چار اولو العزم پیغمبر ہیں جن کی طرح صبر کرنے کا حکم آپ کو دیا گیا ہے ۔(الشنقیطی:۷؍۲۴۱)\nاولو العزم پیغمبر کون کون ہیں؟\nفَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ\nجب نہایت عمدہ اخلاق صبر کا حکم ملا تو عجلت اور جلد بازی سے آپ کو روکا گیا تاکہ صبر جو فوز وفلاح اور نصرت کا ضامن ہے ، جیسے عظیم اخلاق پر صحیح طور سے گامزن رہا جائے ، اسی لئے اللہ تعالىٰ نے کہا: (ولا تستعجل لهم) یعنی جلد بازی نہ طلب کیجئے اور نہ جلد بازی میں بے وقت کوئی کام کیجئے جو ان کو برا لگے ۔ (البقاعی: ۱۸؍۱۹۱)\nآیت میں وضاحت یہ ہے کہ داعی کے اندر دوخوبیوں کو اپنانے سے کمال پیدا ہوگا وہ کیا ہیں؟\nكَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۢ\nاس لئے کہ عذاب کی شدت وہولناکی کی وجہ سے وہ دنیا میں گزارے ہوئے ماہ وسال کےمقدار کو بھلا بیٹھیں گے۔ ارشاد باری ہے: ﴿قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ * قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسَۡٔلِ ٱلۡعَآدِّينَ﴾ [المؤمنون: ١١٢ – ١١٣] “اللہ تعالىٰ دریافت فرمائے گا کہ تم زمین میں باعتبار برسوں کی گنتی کے کس قدر رہے ؟ وہ کہیں گے ایک دن یا ایک دن سے بھی کم ، گنتی گننے والوں سے بھی پوچھ لیجئے ”۔(الطبری: ۲۲؍۱۴۶)\nکافروں کو کیوں لگے گا کہ انہوں نے دنیا میں نہایت ہی مختصر زندگی گزاری؟\nwords\nصَرَفنَاهم نے آپ كي طرف بھيجا.\nقُضِيَپورا كيا۔ رسول الله صلی اللہ علیہ وسلم اس كي تلاوت سے فارغ هوئے.\nمُنذِرِينَالله كي پكڑ سے ڈرانے والے.\nوَيُجِركُموه تمهيں بچائے گا.\nيَعيَ بِخَلقِهِنَّوه ان كو پيدا كرتے هوئے تھكا نهيں.\nبَلاَغٌالله كي طرف سے ان كو تبليغ."],[507,"§محمد\ndeeds\nاللہ تعالىٰ سے دعا کیجئے کہ اے اللہ میرے عمل کی اصلاح فرما اور اسے شرفِ قبولیت بخش.\nغزوۂ بدر کے واقعات کو پڑھئے اور غور کیجئے کہ صحابہ نے دین کی نصرت کے لئے کتنی قربانیاں دیں اور کیسے انہیں اللہ تعالىٰ کی نصرت وتائید حاصل ہوئی.\nکسی مقام پر اللہ تعالیٰ کی مدد اس طرح بھی کیجئے کہ غیبت کے شکار شخص کا دفاع کیجئے یا کسی گناہ گار کو اللہ کے عذاب سے ڈرائیے.\nguid\nایمان اور عمل صالح گناہوں کو مٹاتے اور دل کی اصلاح کرتے ہیں.\nجب شبہات وشہوات کا غلبہ ہو ، اور زمانہ پر فتن ہو ، تو ایسے وقت میں دین کو تھامنا اور اس کا دفاع کرنا اللہ اور اس کے رسول کی نصرت وتائید کے ذرائع میں سے ایک ذریعہ ہے.\nاسلام کی نصرت کا تقاضہ یہ ہے کہ اسلامی احکام وتعلیمات پر عمل کیا جائے اور محرمات سے اجتناب کیا جائے.\nrefl\nوَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضٖۗ\nاس لئے کہ اللہ تعالىٰ ہر چیز پر قادر ہے ، اور اللہ تعالىٰ چاہے تو کافر کبھی بھی غالب وفاتح نہ ہو تاکہ مسلمان ان کی نسل واصل مٹا کے رکھ دے (ولكن ليبلوا بعضكم ببعض) لیکن اللہ تعالىٰ ابتلا وامتحان چاہتا ہے تاکہ جہاد قائم رہے اور سچے وجھوٹے بندوں کی پہچان ہو سکے ، اور اللہ تعالىٰ اس لئے بھی آزماتا ہے ،تاکہ مومن علم وبصیرت کی بنیاد پرصحیح مؤمن بنے ، نہ کہ غالب قوم کی تابعداری میں ایمان لائے، اس لئے اس طرح کا ایمان آزمائشوں اور مصیبتوں کے وقت ٹکتا نہیں ہے۔ (السعدی: ۷۸۵)\nوہ کو ن سا امتحان وابتلاء ہے جس کی بناء پر بعض اوقات کفار ومشرکین مسلمانوں پر غلبہ پا لیتے ہیں؟\nوَٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعۡمَٰلَهُمۡ ٤ سَيَهۡدِيهِمۡ وَيُصۡلِحُ بَالَهُمۡ ٥\n(ويصلح بالهم) یعنی ان کے محورِ فکر کی اصلاح فرماتا ہے تووہ ہر بھلائی کے لئے تیار ، ہر طرح کی برائی اور خوف وبے چینی سے دور رہتا ہے اور اپنے ایمان پر اطمینان کی سانس لیتا ہے ، پھر جب بھی کوئی بندہ راہ خدا میں شہید ہو جاتا ہے تو اللہ تعالىٰ اس کے وارثین کی مدد شہید کی مدد سے زیادہ بہتر طریقے سے کرتا ہے اگر وہ با حیات ہوتے۔ (البقاعی: ۷؍۱۵۳)\n(ويصلح بالهم) کا مفہوم بتائیے ؟\nوَيُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ ٦\nیعنی جنت کے گھر ان پر بہت واضح ہوں گے ، جنت کے گھروں تک بغیر کسی غلطی وسؤال کے رسائی حاصل کر لیں گے ، یوں لگے گا جیسے وہ ان محلوں میں بچپن سے رہتے ہوں ، مومن اپنے درجے ، بیوی اور خدمت گزاروں کو دنیاوی گھر واہل وعیال سے زیادہ پہچانیں گے۔ یہ اکثر علماء ومفسرین کا قول ہے۔(البغوی: ۴؍۱۵۴)\nاللہ تعالىٰ جنتیوں کو جنت کی نعمتوں سے کیسے آگاہ کرے گا؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ ٧\nنام کے مسلمان جو ہر طرح کے گناہوں کا ارتکاب کرتے ہیں پھر آس لگائے رہتے ہیں کہ اللہ عنقریب ہماری مدد کرے گا ، دھوکے میں پڑے ہوئے ہیں، اس لئے کہ یہ لوگ اس جماعت سے خارج ہیں جس سے اللہ نے مدد کا وعدہ کیا ہے ، اللہ کی مدد کا مفہوم یہ ہے کہ مومن اللہ کے دین وکتاب کی مدد کرے اوراللہ کے کلمہ کو بلند وبالا رکھنے کے لئے انتھک محنت ، کوشش اورتگ ودو کرے ، اور حدودِ شریعت کو قائم کرے ، اور احکامِ اسلام پر عمل کرے ، اور محرمات سے بچے ۔(الشنقیطی: ۷؍۲۵۲)\nمومن اللہ کی مدد کیسے کریں گے ؟ اور کیا گناہ گار و نافرمان لوگ نصرتِ الہی کے مستحق ہیں؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ ٧ وَٱلَّذِينَ كَفَرُواْ فَتَعۡسٗا لَّهُمۡ وَأَضَلَّ أَعۡمَٰلَهُمۡ ٨ ذَٰلِكَ بِأَنَّهُمۡ كَرِهُواْ مَآ أَنزَلَ ٱللَّهُ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ ٩\nیہ امت کے لئے وعید ہے ، یعنی اگر وہ اللہ کی مدد ، اس کی راہ میں جہاد اور امر بالمعروف ونہی عن المنکر کو چھوڑ دے ، تو اللہ تعالىٰ اس کو اس کے نفس کے حوالے کر دے گا اور اس کی مدد ترک کر دے گا ، اور اس پر اس کے دشمنوں کو مسلط کر دے گا ، بعض مرتبہ ایسا بھی ہوا ہے کہ جب سابقہ امور میں امت کے اندر سستی وکاہلی پائی گئی اور اس سلسلہ میں ایک دوسرے پر اعتماد کر بیٹھے ،تو بعض فاسق وفاجر لوگ مسلط ہو گئے۔(البقاعی: ۷؍۱۵۵)\nاسلامی احکام وتعلیمات سے انحراف اور ان سے بغض کا انجام کیا ہوتا ہے؟\n۞أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَيۡهِمۡۖ\nجہاں جہاں بھی اللہ نے زمین میں چلنے پھرنے اور سیر وسیاحت کا حکم دیا ہے ،چاہے وہ چلن اور سیر سیاحت حسی ہو یعنی پیدل اور سواری پر ہو یا سیر وسیاحت معنوی ہو یعنی غور وفکر اور اعتبار کی حیثیت سے ہو یا لفظ دونوں نوع کو شامل ہو، وہیں عبرت و نصیحت پکڑنے کی تعلیم دی ہے نیز بچ بچاکر رہنے کی ہدایت بھی دی ہے تاکہ ان پر اسی طرح کا عذاب مسلط نہ ہو جائے جو پچھلی قوم پر مسلط ہوا تھا (ابن القیم: ۲؍۴۵۴)\nاللہ تعالیٰ نے اپنے بندوں کو زمین میں سیر و سیاحت کا حکم دیا ہے، اس میں کیا حکمت ہے؟\nوَأَنَّ ٱلۡكَٰفِرِينَ لَا مَوۡلَىٰ لَهُمۡ ١١\n(لا مولى لهم) یعنی کافروں کا کوئی بھی کارساز ومددگار نہیں جو انہیں سلامتی والے راستے کی طرف رہنمائی کر سکے اور نہ کوئی انہیں عذابِ الہی سے نجات دلا سکے، بلکہ ان کے اولیاء تو شیاطین ہیں جو ان کو روشنی سے نکال کر اندھیروں کی طرف لے جاتے ہیں۔(السعدی: ۷۸۶)\nجب کافروں کے اولیاء طاغوت ہیں تو پھر (ان کا کوئی ساز ومددگار نہیں) کا کیا مطلب ہے؟\nwords\nفَضَربَ الرِّقَابِان كي گردنيں مار دو.\nأَثخَنتُمُوهُمان كا خوب خون بها كر انهيں كمزور كردو.\nفَشُدُّوا الوَثَاقَقيدي كي زنجيريں اچھي طرح كس كر باندھو.\nمَنًّاتم ان پر احسان كرو؛ ان كے قيديوں كو بلا معاوضه رها كركے."],[508,"§محمد\ndeeds\nکھانے سے پہلے بسم اللہ پڑھئے اور کھانے کے بعد الحمد للہ کہیئے اور جانوروں کی طرح بسم اللہ کہے بغیر مت کھائیے.\nوضو اور نمازِ نبوی سے متعلق کسی کتاب کا مطالعہ کیجئے تاکہ آپ کی عبادت مدلل ہو.\nاپنے گناہوں پر اللہ کی بخشش طلب کیجئے اور دعا کیجئے کہ اللہ مومن مردوں اور مومن عورتوں کے گناہوں کو بخش دے.\nguid\nاللہ تعالیٰ کی تباہ وبرباد کردہ ظالم بستیوں میں غور وفکر کیجئے اور عبرت پکڑئیے.\nقیامت کی تیاری نیک عمل کے ذریعہ کیجئے.\nعلم کی اہمیت کو سمجھیئے ، بذریعہ علم ہی آپ کا عمل یقین واعتماد اور دلائل کی روشنی میں انجام پائے گا.\nrefl\nإِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ\nمسلمان جنت میں داخل ہو کر دنیا کی ساری تکلیفوں ومصیبتوں کو بھول جائیں گے ، جنت کی نعمتوں کے ساتھ قربتِ رب کی نعمت سے سرشار ہوں گے پھر کبھی احزان واحلام میں مبتلا نہ ہوں گے اور ہمیشہ جنت میں رہیں گے اور کبھی وہاں سے نکلنا نہیں چاہیں گے ، یہ ساری نعمتیں دنیاوی تنگی ومشکلات کو جھیلنے کے عوض میں ملیں گے ، اللہ تعالىٰ نے ان سے محبت اور ان کی عزت افزائی میں اپنی خدمت وعبادت کے لئے انہیں موقع دے دیا ہے اور اپنی قربت ان کے لئے لازم کر دیا ہے ۔(البقاعی: ۱۸؍۲۱۴)\nمومنوں پر دخولِ جنت کے اثرات کیا ہیں؟\nوَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ ١٢\nکافرچوپایوں کی طرح دنیا کے مزے لیتے ہیں اپنے کل سے بے خبر ہوکر صرف پیٹ اور جنس کے تقاضوں کے بابت ہی سوچتے ہیں،بولا جاتا ہے کہ مومن دنیا میں توشۂ آخرت جمع کرتا ہے ، اور منافق زیب وزینت اختیار کرتا ہے ، اورکافر لطف اندوزی کرتا ہے ۔ (القرطبی: ۲؍۲۵۷)\nدنیاوی زندگی میں کافر کا محور کیا ہے ؟ اور اس تعلق سے مومن ، منافق اور کافر کے عزائم میں کیا فرق ہے؟\nوَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ ١٢\nمنکرینِ توحید ورسالت اور کفار دنیا کی زیب وزینت ، مال ومتاع اور آرائش وزیبائش سے خوب لطف اندوزی کرتے ہیں وہ بلا علم ومعرفت جو کچھ کھاتے ہیں ان کے کھانے کی مثال چوپایوں کی طرح ہے جنہیں صرف چارہ کھانے اور پیٹ کے تقاضے پورے کرنے کی فکر دامن گیر ہوتی ہے ۔ (الطبری: ۲۲؍۱۶۴)\nاس دنیا میں کافروں اور چوپایوں کے درمیان وجہ ِشباہت کیا ہے؟\nوَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ ١٢\nکافر مثل چوپایوں کے کھاتے ہیں یعنی بطور تلذذ وفرحت وانبساط ، جہاں سے ہاتھ آ جائے ، ساتوں آنتوں میں ، پیٹ بھر کے حلال وحرام کی تمیز کئے بغیر ، کیوں کہ اللہ نے انہیں دنیوی نعمتوں سے نوازا ہے ، وسعت وکشادگی دی ہے اور دنیا کے لئے ان کو فارغ کر دیا ہے یہاں تک کہ وہ دنیا میں مصروف ہو گئے اور اللہ سے غافل ہو گئے۔ (البقاعی: ۱۸؍۲۱۴)\nبعض لوگوں کو دنیاوی نعمتوں سے نوازا جاتا ہے اور ربِ واحد کی عبادتوں سے محروم رکھا جاتاہے، اس میں کیا اشارہ ہے؟\nفَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَٱللَّهُ يَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَىٰكُمۡ ١٩\nحضرت ابو موسىٰ اشعری(رضی اللہ عنہ) سے روایت ہے کہ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: میں ہر دن سو مرتبہ اللہ سے مغفرت طلب کرتا ہوں ۔حضرت عبد اللہ بن عمر(رضی اللہ عنہما )کہتے ہیں : ہم مجلس میں رسول اللہ صلی اللہ علیہ وسلم کے توبہ واستغفار کو شمار کیا کرتے تھے ، آپ اس دعا کو سو مرتبہ پڑھا کرتے تھے : “رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ اِنَّكَ اَنْتَ التَّوَّابُ الرَّحِيْمُ” اے میرے رب ! تو مجھے بخش دے اور میری توبہ قبول کر ، یقینا تو توبہ قبول کرنے والا اور رحم کرنے والا ہے ۔(الألوسی: ۲۵؍۲۹۴)\nنبی کریم صلی اللہ علیہ وسلم کا قرآن میں تدبر اور اس پر عمل کے تعلق سے ایک مثال بیان کیجئے\nفَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ\nسفیان بن عیینہ سے روایت ہےکہ ان سے علم کی فضیلت کے بارے میں سوال ہوا تو انہوں نے جواب دیا : کیا تو نے ارشادِ باری تعالىٰ نہیں سنا جس کا آغاز علم سے ہوا ہے: (فاعلم أنه لا إله إلا الله واستغفر لذنبك) اور پھر علم کے بعد عمل کا حکم ہوا ہے، فرمایا : ﴿ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٌ...﴾ إلى قوله: ﴿سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ...﴾ (الحدید:۲۰-۲۱) جان رکھو کہ دنیا کی زندگی کھیل تماشہ ہے اور زینت (وآرائش) اور تمہارے آپس میں فخر (وستائش) اور مال واولاد کی ایک دوسرے سے زیادہ طلب (وخواہش) ہے (اس کی مثال ایسی ہے) جیسے بارش کہ (اس سے کھیتی اُگتی اور) کسانوں کو کھیتی بھلی لگتی ہے پھر وہ خوب زور پر آتی ہے پھر (اے دیکھنے والے) تو اس کو دیکھتا ہے کہ (پک کر) زرد پڑ جاتی ہے پھر چورا چورا ہوجاتی ہے اور آخرت میں (کافروں کے لئے) عذاب شدید اور (مومنوں کے لئے) خدا کی طرف سے بخشش اور خوشنودی ہے۔ اور دنیا کی زندگی تو متاع فریب ہے(۲۰)آو دوڑو اپنے رب کی مغفرت کی طرف۔ اور فرمایا: ﴿ٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٌ﴾ [الأنفال: ٢٨] اور تم اس بات کو جان رکھو کہ تمہارے اموال اور تمہاری اولاد ایک امتحان کی چیز ہے ۔ پھر فرمایا: (فاحذروهم) [التغابن: ١٤] پس تم ان سے ہوشیار رہنا ، اور فرمایا: ﴿وَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ...﴾ [الأنفال: ٤١] جان لو کہ تم جس قسم کی جو کچھ غنیمت حاصل کرو ، پھر بعد میں عمل کا حکم ہوا ۔ (القرطبی: ۱۹؍۲۶۷)\nآیتِ کریمہ علم کے بعد عمل کی فضیلت کیسے بیان کرتی ہے؟ اس کی وضاحت کیجئے.\nوَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ\nجب آپ کومومنوں کے لئے استغفار کا حکم ملا ہے ، اور استغفارِ نبوی گناہوں کو مٹانے اور عذابوں کو دور کرنے کا ذریعہ ہے تو امر ِاستغفار کا لازمی تقاضہ یہ ہے کہ آپ مومنوں کو نصیحت فرمائیں ، اپنے لئے جو نیکی وبھلائی پسند کرتے ہیں ان کے لئے بھی کریں اور جو بدی وبرائی اپنے لئے ناپسند کرتے ہیں ان کے لئے بھی ناپسند کریں ، اورانہیں بھلی باتوں کا حکم دیں اورنقصاندہ باتوں سے منع فرمائیں ، ان کی غلطیوں کو معاف کریں اور عیوب پر پردہ ڈالیں، ان کے دلوں کو جوڑیں اور ان کی صفوں میں اتحاد واجتماعیت پیدا کرنے کی کوشش کریں تاکہ ان کےدلوں سے حسد اورکینہ کپٹ دور ہوجائے جو عداوت و اختلاف اور کثرت ِگناہ کا باعث ہے۔ (السعدی: ۷۸۷-۷۸۸)\nمومن مردوں اور عورتوں کے لئے استغفار کے لازمی معانی کیا ہیں؟\nwords\nمَثوىًٹھكانا / مسكن.\nغَيرِ آسِنٍجو بدلا نه هو / اس سے بو نه آتي هو.\nآنِفًاابھي ابھي.\nجَاءَ أَشرَاطُهَااس كي نشانياں ظاهر هو گئيں.\nفَأَنَّىان كے ليے يه كهاں سے هو گيا.\nمُتَقَلَّبَكُموه تم پر دن كے جاگتے ميں تصرف كرتا هے.\nوَمَثوَاكُمرات كو نيند كے ليے تمهارا ٹھكانا."],[509,"§محمد\ndeeds\nبعض رشتہ داروں کی زیارت کیجئے یا فون پر رابطہ رکھئے تاکہ صلہ رحمی کا حق ادا ہو سکے.\nقرآن کے اس صفحہ کو غور سے پڑھئے اور یہاں غیر مذکور تین فائدے مستنبط کیجئے.\nدعا کیجئے کہ اللہ تعالىٰ آپ کے دل کو سلامت رکھے اور نفاق ، ریا اور عجب وتکبر سے اسے پاک صاف کر دے.\nguid\nاللہ کے ساتھ سچائی کا راستہ اختیار کرنےوالوں میں سے ہو جائیں.\nقطع رحمی کے خطرات ونقصانات.\nبندوں کے تمام بھیدوں کو اللہ تعالىٰ ظاہر کرنے پر قدرت رکھتا ہے.\nrefl\nفَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ ٢٢ أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ ٢٣\nاس سے معلوم ہوا کہ ہر وہ شخص جوامر بالمعروف کا فریضہ انجام دے گا اور اہلِ منکَر سے جہادکرے گا تو وہ زمین میں فساد پھیلانے اور قطعِ رحمی سے محفوظ رہے گا ، اور جو شخص اس دینی فریضہ کو ترک کر دے گا وہ اہلِ منکر کی گرفت میں آجائے گا۔(البقاعی: ۷؍۱۶۹)\nمسلم معاشرے پر امر بالمعروف ونہی عن المنکر اور جہاد فی سبیل اللہ کے ترک کرنے پر کیا انجام مرتب ہوتا ہے؟\nفَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ ٢٢\nرشتہ داریاں دو قسم کی ہیں: ایک عام اور دوئم خاص ، عام رشتہ داریوں میں دین کی رشتہ داریاں آتی ہیں ، اس رشتہ داری کا تقاضا یہ ہے کہ ایمان پر جمے رہیں ، اہل ایمان سے محبت کریں ، ان کی مدد کریں ، انہیں نصیحت کریں ، ان کے مابین انصاف کریں اور انہیں نقصان پہنچانے سے بچیں اور ان کے معاملات میں عدل سے کام لیں اور ان کے واجب حقوق کو ادا کریں یعنی مریضوں کی عیادت کریں ، میتوں کو غسل دیں ، نمازِ جنازہ پڑھیں اور دفن وغیرہ میں شریک رہیں اور خاص رشتہ داریوں میں والدین کی طرف سے آنےوالی رشتہ داریاں ہیں۔ ان قرابتداروں کے خصوصی حقوق ہیں یعنی نان ونفقہ ، خبر گیری ، ان کی ضرورت کے اوقات میں دیکھ ریکھ سے آنکھ نہ چرانا ، اور ان کے عام حقوق کو ادا کرنا بدرجۂ اولىٰ اہم ہے ، رشتہ داروں کے حقوق میں تعارض وتصادم ہو تو سب سے قریبی رشتہ داروں کے حقوق مقدم ہوں گے۔ (القرطبی: ۱۹؍۲۷۷)\nرحم سے مراد کیا ہے ؟ اور ان کے حقوق کیا ہیں؟\nفَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ ٢٢ أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ ٢٣\nآیت: (أولئك الذين لعنهم الله)کے مستحق وہ لوگ ہیں جو زمین میں فساد پھیلاتے ہیں اور قطعِ رحمی کرتے ہیں یہی لوگ اللہ کی رحمت سے دور ہیں ، اللہ نے ان کے کانوں کو بہرا کر دیا ہے یعنی اپنے کانوں سے جو مواعظ سنتے ہیں انہیں سمجھنے سے قاصر ہیں ، اور اللہ نے ان کی آنکھوں کو اندھا کر دیا ہے ، یعنی ان کی عقل ماری گئی ہے جس کی وجہ سے اللہ کی نشانیاں ان پر واضح نہیں ہوتیں اور عبرت کی چیزوں اور ان کے ثبوتوں سے وہ نصیحت نہیں پکڑتے ۔(الطبری: ۲۲؍۱۷۸)\nآیت میں اللہ نے کن لوگوں پر لعنت بھیجی ہے ؟اور ان کے آنکھوں کے اندھے پن کا کیا معنى ہے؟\nأَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ ٢٤\nگویا دل بند دروازوں کے قائم مقام ہے جس پر تالا پڑا ہوا ہے جب قفل کھولا نہیں جاتا تو دروازہ کھولنا اور اندر رسائی حاصل کرنا محال ہے ، بعینہ جب تک دل کےمہر اور تالے کھولے نہیں جاتے ایمان وقرآن دل کے اندر داخل نہیں ہو سکتے۔ (ابن القیم: ۲؍۴۵۴)\nآیت میں دلوں کے کھولنے اور قرآن کے دلوں کےاندر تک پہنچنے کا ایک طریقہ بتایا گیا ہے ، اس کی وضاحت کیجئے.\nأَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ ٢٤\nاس آیت کا معنی یہ ہے کہ کیا وہ قرآن کو سمجھنے کی کوشش نہیں کرتے تاکہ وہ جھنجوڑنے والی نصیحتوں ، واضح نشانیوں اور قطعی دلیلوں کو جان سکے جو عقل وفہم رکھنے والوں کے لئے کافی ہوتی ہیں اور کفر وشرک اور معصیت کے ارتکاب سے روک دیتی ہیں۔ (الشوکانی: ۵؍۳۸)\nقرآن میں حصولِ تدبر کی علامت کیا ہے؟\nإِنَّ ٱلَّذِينَ ٱرۡتَدُّواْ عَلَىٰٓ أَدۡبَٰرِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَى ٱلشَّيۡطَٰنُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ لَهُمۡ ٢٥\nاللہ تعالىٰ مرتدین کی داخلی کیفیت وحالت سے آگاہ کر رہا ہے کہ انہوں نے ہدایت وایمان کو ترک کرکے راہِ کفر وضلال کو دلیل وبرہان کے ساتھ اختیار نہیں کیا ہے بلکہ ان کے دشمن(شیطان) کے ان کو گمراہ کرنے، ان کی تزیین اور ان کی ترغیب کی بناء پر ہے۔ (السعدی:۷۸۹)\nبعض مسلمانوں کے مرتد ہونے کا سبب کیا ہے؟\nفَكَيۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ ٢٧ ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُواْ مَآ أَسۡخَطَ ٱللَّهَ وَكَرِهُواْ رِضۡوَٰنَهُۥ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ ٢٨\nمرتدین وہ راہ چلے جس سے انہوں نے اللہ کو ناراض کر دیا اور انہوں نے اللہ کی رضا مندی کو برا جانا ، دونوں باتیں ایک دوسرے کے قائم مقام ہو سکتی ہیں لیکن دونوں کو جمع کرنے میں لطیف اشارہ یہ ہے کہ فرشتوں کا ان کے چہروں پر مارنا اس مناسبت سے ہے کہ انہوں نے اللہ کو ناراض کرنے کے لئے اقدام واقبال سے کام لیا ، اور فرشتوں کا ان کے سرینوں پر مارنا اس مناسبت سے ہے کہ انہوں نے اللہ کی رضامندی کو برا جاننے کے لئے اعراض وادبار سے کام لیا۔ (ابن عاشور: ۲۶؍۱۱۹)\nمشرکین نے اللہ کی ناراضگی کی راہ اختیار کیا اور اللہ کی رضامندی کو برا جانا ، اس میں اور فرشتوں کا بوقتِ وفات ان کے چہروں وسرینوں پر مارنے میں کیا مناسبت ہے؟\nwords\nمَرَضٌشك / نفاق.\nالمَغشِيِّ عَلَيهِشدت خوف سے بيهوش پڑا.\nعَزَمَ الأَمرُجنگ كرنا واجب هو جائے.\nفَهَل عَسَيتُمشايد كه تم / قريب هے كه تم.\nتَوَلَّيتُمتم اس پر ايمان لانے سے منه موڑتے هو.\nارتَدُّوا عَلَى أَدبَارِهِموه حالت كفر ميں واپس پلٹے.\nسَوَّلَ لَهُمان كي خطاؤوں كو مزين كركے پيش كيا.\nإِسرَارَهُمجس كو وه چھپاتے هيں/ وه اسے راز ميں ركھتے هيں.\nأَضغَانَهُمان كا حقد / حسد."],[510,"§محمد\ndeeds\nقرآن کریم میں وارد منافقین کی تین صفتوں کو ذکر کیجئے.\nدعا کیجئے کہ اللہ تعالىٰ آپ کوصبرکرنے والوں میں سے بنائے.\nآج اللہ کی راہ میں اپنی جیب خرچ کا کچھ حصہ دے دیجئے اور اپنے اس خاص مال پر بخیلی نہ کیجئے.\nguid\nقضاء وقدر پر ایمان آزمائشوں ومصیبتوں پر صبر کا متقاضی ہے.\nاپنے تمام اعمال میں اخلاص پیدا کیجئے اور لوگوں کی رضا وستائش کا خیال دل میں نہ لائیے.\nمومن اپنے ایمان کی بدولت مضبوط اور قوی ہوتا ہے بزدل اور کمزور نہیں ہوتا.\nrefl\nوَلَوۡ نَشَآءُ لَأَرَيۡنَٰكَهُمۡ فَلَعَرَفۡتَهُم بِسِيمَٰهُمۡۚ\nاے محمد صلی اللہ علیہ وسلم اگر ہم چاہتے تو ان منافقوں کو آپ ایک ایک کرکے اپنی آنکھوں سے دیکھ لیتے ، لیکن تمام منافقوں کے لئے اللہ نے ایسا اس لئے نہیں کیا کیوں کہ وہ اپنے بندوں کی پردہ پوشی کرنا چاہتا ہے ، اور یہ چاہتا ہے کہ ان کے اعمال کو ظاہر پر محمول کیا جائے اور ان کے باطن کو اللہ کے حوالے کر دیا جائے ۔ (ابن کثیر: ۴؍۱۸۳)\nاللہ تعالیٰ نے مسلمانوں سے منافقین کے بارے میں کیوں کھول کر بیان نہیں کیا؟\n۞يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَلَا تُبۡطِلُوٓاْ أَعۡمَٰلَكُمۡ ٣٣\nارشاد باری:(ولا تبطلوا أعمالكم) چار معانی کا احتمال رکھتا ہے ، ۱ایمان کے بعد کفر کرکے اپنے اعمال ضائع مت کرو۔ ۲نیکیوں کو گناہوں کا ارتکاب کرکے برباد مت کرو۔ ۳ریا وکبر کے ذریعہ اپنے اعمال کو غارت مت کرو۔ ۴عمل کو مکمل ہونے سے پہلے ختم کرکے اپنے اعمال کو ضائع وبرباد مت کرو۔ (ابن جزی: ۲؍۳۴۳)\nعملوں کو باطل کرنے والی چیزوں کو آیت کی روشنی میں بیان کیجئے.\nفَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ\nآیت: (والله معكم) میں مسلمانوں کے لئے دشمنوں پر فتح ونصرت کی عظیم بشارت دی گئی ہے۔(ابن کثیر: ۴؍۱۸۴)\nمسلمانوں کے لئے اللہ کی معیت کے کیا اثرات مرتب ہوتے ہیں؟\nفَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ\nجب تم تعداد اور قوت وطاقت میں دشمنوں سے برتر ہو تو کافروں کے ساتھ صلح اور کمزوری کا مظاہرہ مت کرو ، لیکن جب کافروں کی تعداد اور قوت وطاقت مسلمانوں سے زیادہ ہوں اور حاکم وقت صلح اور جنگ بندی کو مسلمانوں کے حق میں نافع ومفید سمجھتا ہو تو وہ ان کے ساتھ صلح وجنگ بندی کا معاہدہ کر سکتا ہے۔ (ابن کثیر: ۴؍۱۸۴)\nآیت میں وضاحت ہے کہ مسلمان دشمنوں سے قوت میں افضل ہوں تو کیا موقف اختیار کرے ، لیکن کافروں کے بالمقابل مسلمان کمزور ہو تو انہیں کون سا موقف اختیار کرنا چاہیئے ؟\nإِنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ ٣٦\nراجح بات یہ ہے کہ یہ آیت ما قبل آیت پر عطف ہے ، یعنی مذکورہ ممنوع امر سے اجتناب بہترین تقوىٰ ہے ، اور ایک بات یہ ہےکہ صلح کے پیچھے جنگ میں خرچ ہونے والے مال کی حفاظت مقصود ہو سکتا ہے ، اس لئے مومنوں کو ایمان وتقوىٰ کی یاد دلائی گئی ہے تاکہ مال و جان کی محبت(وہن) کو دل سے نکال دیں ، کیوں کہ(وہن) سے منع کیا گیا ہے ، اور صلح کی دعوت دینے سے بھی منع کیا گیا ہے ، گویا ان ممنوعات سے دامن بچانا تقوىٰ کی علامت ہے۔(ابن عاشور: ۲۶؍۱۳۳)\nامت کو لاحق(وہن) کا علاج کیا ہے؟ آیت کی روشنی میں بتائیے.\nوَإِن تُؤۡمِنُواْ وَتَتَّقُواْ يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ ٣٦\nاجر وثواب عطا کرنے کے لئے تم سے تمہارا رب مال نہیں مانگتا بلکہ وہ تمہیں ایمان واطاعت کا حکم دیتا ہے تاکہ تمہیں جنت سے نوازے ۔ اس آیت کی نظیر یہ آیت ہے: ﴿مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقٖ﴾ [الذاريات: ٥٧] میں ان سے روزی نہیں چاہتا۔اور اس آیت کا ایک معنی یہ بتایا گیا ہے کہ حضرت محمد صلی اللہ علیہ وسلم تم سے مال نہیں مانگتے ، اس آیت کی نظیر یہ آیت ہے :﴿قُلۡ مَآ أَسَۡٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ﴾[سورة ص: ٨٦] فرمادیں: میں تم سے اس پر کوئی بدلہ طلب نہیں کرتا۔ اور آیت کا ایک معنی یہ بھی بتایا گیا ہے کہ اللہ اور اس کے رسول تم سے زکوۃ میں کل مال کا مطالبہ نہیں کرتے بلکہ نہایت معمولی رقم یعنی صرف ڈھائی فیصد کا مطالبہ کرتے ہیں لہذا تم اسے خوش دلی سے ادا کرو۔ (القرطبی:۴؍۱۶۳)\nسچے عالم کی نشانی یہ ہے کہ وہ لوگوں سے مال کا مطالبہ نہیں کرتے ، بتایئے آیت سے یہ کیسے سمجھ میں آتا ہے؟\nهَٰٓأَنتُمۡ هَٰٓؤُلَآءِ تُدۡعَوۡنَ لِتُنفِقُواْ فِي سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبۡخَلُۖ وَمَن يَبۡخَلۡ فَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ وَإِن تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ ثُمَّ لَا يَكُونُوٓاْ أَمۡثَٰلَكُم ٣٨\n(ومن يبخل فإنما يبخل عن نفسه) یعنی بخل کا ضرر بخیل کو ہی اٹھانا پڑتا ہے ، کیونکہ بخیل انفاق کے اجر وثواب سے محروم ہو جاتا ہے۔ (وإن تتولوا يستبدل قومًا غيركم) یعنی اس قوم کو لائے گا جو تمہاری طرح بخیل نہ ہوگی بلکہ انفاق فی سبیل اللہ میں رغبت رکھے گی۔ (ابن جزی: ۲؍۳۴۴)\nبدلہ عمل کی طرح ہی ملتا ہے ، اس آیت سے یہ معنى کیسے نکلتا ہے؟ وضاحت کیجئے.\nwords\nبِسِيمَاهُمان كي ظاهري نشانياں.\nلَحنِ القَولِجو ان كےكلام سے ظاهر هوتا هے؛ اور ان كے مقاصد پر دلالت كرتا هے.\nوَلَنَبلُوَنَّكُمهم ضرور تمهارا امتحان ليں گے.\nوَشَآقُّوااس كي مخالفت كي ؛ اس سے جنگ كي.\nيَتِرَكُم أَعمَالَكُموه تمهارے اعمال كا ثواب كم كرے گا.\nفَيُحفِكُمپس وه تم سے چمٹ جائے۔وه تمهيں مجبور كرے.\nأَضغَانَكُمتمهارا حسد؛ حقد اور بغض."],[511,"§الفتح\ndeeds\nحضرت محمد صلی اللہ علیہ وسلم پر درود بھیجئے ، یہ بھی رسول اللہ صلی اللہ علیہ وسلم کی مدد اور آپ صلی اللہ علیہ وسلم کے ساتھ ادب کا طریقہ ہے.\nنبی کریم صلی اللہ علیہ وسلم کی سنتوں کی تعظیم کرتے ہوئے کسی ایک سنت پر عمل کیجئے ، مثلا مسواک کیجئے.\nذکر واذکار اور تسبیح کو صبح وشام کا وظیفہ بنا لیجئے.\nguid\nصلح حدیبیہ کے ذریعہ اللہ تعالىٰ مسلمانوں پر احسان جتلا رہا ہے.\nاللہ کے ساتھ حسن ظن رکھئے ، اللہ تعالىٰ حسن ظن کا اعتبار کرتا ہے.\nآپ صلی اللہ علیہ وسلم کی سیرتِ طیبہ کو بیان کرنا ، اور آپ پر درود وسلام بھیجنا ، اور آپ کی سنتوں پر چلنا وغیرہ نبی کریم صلی اللہ علیہ وسلم کی تعظیم کا ہی حصہ ہے.\nrefl\nإِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ١\nزہری(رحمہ اللہ) فرماتے ہیں : صلح حدیبہ سے عظیم فتح کوئی فتح نہ تھی ، اس کے بعد کافروں ومسلمانوں میں میل ملاپ بڑھ گیا، کافروں نے مسلمانوں کی تہذیب وزبان کو پرکھا ، اور اسلام ان کے دلوں میں رچ بس گیا ، تین سالوں میں بہت سے لوگ مسلمان ہو گئے اور ملتِ اسلامیہ میں اضافہ ہو گیا ۔ (البغوی: ۴؍۱۶۶)\nصلح حدیبیہ ایک فتح تھی ، ایک نصرت تھی ، کیسے؟\nإِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ١ لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ\nاللہ تعالىٰ نے اس فتح پر کئی چیزوں کو مرتب کرتے ہوئے فرمایا: (ليغفر لك الله ماتقدم من ذنبك وما تأخر) مغفرتِ ذنوب کی وجہ اللہ بہتر جانتا ہےیہ ہے کہ آپ کی صلح کے سبب بہت سے لوگوں نے اسلام قبول کیا اور طاعت وبندگی میں بے شمار اضافہ ہوا ، اور صلح کے شروط وبنود پر آپ صلی اللہ علیہ وسلم نے تحمل وصبر کا بے انتہا مظاہرہ کیا جو صرف اولو العز م پیغمبر ہی کر سکتے ہیں ۔ (السعدی: ۷۹۱)\nفتح پر اللہ تعالىٰ نے نبی صلی اللہ علیہ وسلم کے اگلے پچھلے گناہوں کی مغفرت کو مرتب کیا ہے ، کیوں؟\nإِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ١ لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا ٢\nاور اللہ تعالىٰ نے ہدایت ونصرت وغلبہ کو ایک ساتھ جمع کر دیا ہے ، اس لئے کہ یہ دونوں کامل سعادت و کامیابی کی بنیادیں ہیں ، ہدایت اللہ اور اس کے دین کی معرفت اور اس کی مرضی اورفرمانبرداری کے مطابق جینے کا نام ہے اور یہی علمِ نافع اور عملِ صالح ہے ، اور نصرت وغلبہ کا مطلب اللہ کے دین کو حجت وبرہان اور سیف وسنان کے ذریعہ نافذ کرنے کی مکمل قدر ت وقوت حاصل ہونے کا نام ہے ، یعنی دلیلوں وحجتوں سے مخالفین کے دلوں پر راج کریں اور طاقتوں وقوتوں سے ان جسموں پر غلبہ پائیں۔ اللہ تعالىٰ کامیابی کے ان دونوں اصولوں کو بکثرت اکٹھے ذکر کرتا ہے کیوں کہ انہی کے ذریعہ دعوتِ دین کا فریضہ اپنے کمال کو پہنچےگا اور تمام باطل ادیان پر اللہ کے دین کو غلبہ حاصل ہوگا ۔ (ابن القیم:۳؍۵۶)\nان آیتوں میں اللہ تعالىٰ نے اپنے رسول کے لئے ہدایت ونصرت کو اکٹھے کیوں بیان کیا ہے؟\nلِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا ٢\nحضرت مغیرہ بن شعبہ(رضی اللہ عنہ) سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم لمبی نماز پڑھتے تھے یہاں تک کہ آپ کے پیر سوج جاتے تھے آپ سے کہا جاتا : کیا اللہ تعالىٰ نے آپ کے اگلے پچھلے گناہوں کو معاف نہیں کر دیا ہے؟ آپ جواب میں فرماتے : کیا میں شکر گزار بندہ نہ بنوں؟ (الشوکانی: ۵؍۴۶)\nآپ اتنی دیر تک نماز کیوں پڑھتے تھے کہ آپ کے پیر سوج جاتے تھے جبکہ آپ کے اگلے پچھلے گناہ معاف ہیں؟\nهُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ٤\nرازی(رحمہ اللہ) کہتے ہیں: سکون کا مطلب دراصل اللہ کے وعدے پر اعتماد وبھروسہ اور حکم الٰہی پر صبر کرنا ہے لیکن یہاں سکون سے مراد وہ معنیٰ مقررہ ہے جو فوزوفلاح اور قوت وروحانیت سے عبارت ہے، جو خائف و غمگین افراد کے لئے سکون واطمینان اور تسلی کا باعث ہے اور اسی سکون کا اثر وقار ، خشوع وخضوع اور تمام معاملات میں خود اعتمادی ہے ۔(البقاعی: ۱۸؍۲۸۴)\nمومن بندے پر سکونت کے کیا اثرات مرتب ہوتے ہیں؟\nلِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ\nکتاب وسنت کے دلائل سے ثابت ہے کہ ایمان گھٹتا بڑھتا ہے ، اور یہی بلاشبہ حق بات ہے ،اور یہی اہل سنت وجماعت کا مسلک ہے۔ (الشنقیطی ۷؍۳۹۴)\nاس آیت سے اہل سنت وجماعت کے بعض عقیدہ کا ثبوت ملتا ہے ، وہ عقیدہ کیا ہے؟\nلِّتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ\nیہاں تعزیر کا معنى مدد واعانت کے ذریعہ آپ کوقوت پہنچانا ہے اور یہ اطاعت وفرمانبرداری اور تعظیم کا متقاضی ہے ، اور توقیر کا مطلب آپ کی عزت ، ادب اور تعظیم ہے۔ (الطبری: ۲۲؍۲۰۸)\nآیت میں تعزیر وتوقیر سے کیا مراد ہے؟ اور وہ کیسے کی جائے گی؟\nwords\nفَتحًا مُبِينًاكھلي هوئي فتح / صلح حديبيه ؛ سن چھ هجري.\nالسَّكِينَةَاطمينان اور ثبات.\nظَنَّ السَّوءِبدگماني۔ كه الله تعاليٰ هرگز اپنے دين كي مدد نهيں كرے گا.\nعَلَيهِم دَائِرَةُ السَّوءِان كے ليے بدعا هے۔ كه عذاب او رپكڑ تم پر هي آئے.\nوَتُعَزِّرُوهُتم الله تعاليٰ كي نصرت كرو.\nوَتُوَقِّرُوهُتم الله كي عظمت بيان كرو."],[512,"§الفتح\ndeeds\nنماز كى پابندى کیجئے ،یہ بھى عہد میں داخل ہے جس كا پورا كرنا ضرورى ہے.\nمعمولى ہى سہى ، صدقہ وخیرات دیجئے.\nبعض عبادتوں پر آپ اور آپ كے بعض اہل خانہ ایك دوسرے كى مدد كیجئے.\nguid\nالله كےساتھ یا اس كے بندوں كےساتھ كئے گئےاپنے عہدوپیمان كو یاد كیجئے اور انہیں پورا كیجئے.\nہر معاملہ میں اپنے رب كےساتھ حسنِ ظن ركھئے كیونكہ الله كےساتھ بدظنى منافقوں كى خصلت ہے.\n(لا الہ الا الله) كے شروط میں سے الله اور اسكے وعد ووعید اور تمام باتوں پر یقین كرنا بھی شامل ہے.\nrefl\nفَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ\nاس لئے كہ وه عہد شكنى كركےاُس زمره سے نكل جائےگا جس سے الله تعالىٰ نے وفاءِ بیعت پر جنت كا وعده كیا ہے، اور اس نے ایسا كركے اپنے آپ كو ہى نقصان پہنچایا ہے، رہى بات رسول صلی اللہ علیہ وسلم كى تو الله تعالىٰ دشمنان رسول پر اپنے رسول كا حامى وناصر ہے چاہے لوگ بیعت كو توڑ دیں یا اسے پورى كریں ۔ (الطبرى: ۲۲؍۲۱۰)\nانسان کا اپنے دین کے ساتھ غداری کرنے سے کس کو نقصان پہونچتا ہے؟\nيَقُولُونَ بِأَلۡسِنَتِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ\nجب منافقوں نے آپ سے طلبِ مغفرت كیلئے دل سے نہیں بلكہ استہزاءو مذاقاً كہا تھا،اور ان كا باطن ظاہر سے میل نہیں كھا رہا تھا، تو الله نے انہیں اپنے اس ارشاد سے رسوا كردیا : (يقولون بألسنتهم ما ليس في قلوبهم ) اور منافقوں كا رویہ ایسا ہى رہتا ہے۔ (الشوكانى: ۵؍۴۸)\nمنافقین کانبی صلی اللہ علیہ وسلم سے طلبِ مغفرت کا کیا مقصد ہے ؟\nقُلۡ فَمَن يَمۡلِكُ لَكُم مِّنَ ٱللَّهِ شَيًۡٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرَۢا ١١\nكوئى بھى الله تعالیٰ كے ضرر ونفع كو روك نہیں سكتا ، اہل وعیال اور مال كےساتھ مصروفیت كا بہانہ كوئى عذر نہیں ہے، اگر الله ان كو نقصان پہنچاناچاہے تو وه ٹال نہیں سكتے، اور اگر الله تعالىٰ تمہارےساتھ نفع كا اراده ركھے تو دشمنوں كى دشمنى بھى اسے روك نہیں سكتى۔(الألوسى: ۱۳؍۲۵۳)\nدین كى مدد ونصرت ترك كركے بال بچوں كےساتھ مشغولیت كا عذر پیش كرنا كیا الله كےنزدیك قابلِ قبول ہے؟\nبَلۡ ظَنَنتُمۡ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰٓ أَهۡلِيهِمۡ أَبَدٗا وَزُيِّنَ ذَٰلِكَ فِي قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ وَكُنتُمۡ قَوۡمَۢا بُورٗا ١٢\nنبى صلی اللہ علیہ وسلم كى باسلامت واپسی كا ادنى ا حتمال بھى ان كے حاشیۂ خیال میں نہ آیا بلكہ ان كى ہلاكت وبربادى كا حسین خواب ہى سجاتےرہے اور خوش ہوتےرہے۔ احمقوں اور گھٹیا سوچ ركھنے والوں كا یہى حال رہاہے كہ جو سوچ لیا سو سوچ لیا، واقعہ كے دوسرے رخ كا احتمال بھى فرض نہیں كرتے۔ (ابن عاشور: ۲۶؍۱۶۴)\nمنافقوں كے لئے ڈھیل ہے كہ وه مومنوں كے تعلق سے غلط خیال كو دل میں پالتے رہیں ، آیت كى روشنى میں اس كى وضاحت كیجئے.\nيَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ١٤\nآیت میں مغفرت كو مقدم كیا گیا ہے (يغفر لمن يشاء ويعذب من يشاء) تاكہ انسان کے اندر مغفرت پانے كى آرزو جاگے اور وه ماضى كا تدارك كرنے كیلئے آگے بڑھے، یہ آیت آنے والی آیت (قل للمخلفين من الأعراب) إلى قوله: (فإن تطيعوا يؤتكم الله أجرًا حسنًا) كیلئے جو ایك وعده پر مشتمل ہےتمہید كى حیثیت ركھتى ہے۔(ابن عاشور: ۲۶؍۱۶۶)\nآیت كریمہ میں مغفرت كو عذاب پر كیوں مقدم كیا گیا ہے؟\nسَيَقُولُ ٱلۡمُخَلَّفُونَ إِذَا ٱنطَلَقۡتُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ يُرِيدُونَ أَن يُبَدِّلُواْ كَلَٰمَ ٱللَّهِۚ\nیعنی منافقین اہل ِحدیبیہ سے كئےگئے وعده كو بدلنا چاہتے تھے یعنى الله تعالىٰ نے اہل حدیبیہ سے وعده كرركھا تھا كہ غزوۂ خیبر سے جتنا بھى ما ل غنیمت حاصل ہوگا وه صرف حدیبیہ میں شریك ہونے والوں كا حصہ ہوگا، اور مخلفین مال غنیمت میں اہل حدیبیہ كےساتھ شریك ہونا چاہتےتھے ، گویا منافقین الله كے وعدے میں یہى تبدیلى چاہتےتھے ۔ (ابن جزى: ۲؍۳۴۹)\nمتخلفین اورمنافقین كى چاہت و خواہش مال غنیمت كے اردگرد ہى گھومتى ہے، آیت سے اسكى وضاحت كیجئے.\nفَسَيَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُواْ لَا يَفۡقَهُونَ إِلَّا قَلِيلٗا ١٥\nمنافقین كہیں گے كہ تم مال غنیمت پر ہم سے حسد كرتےہو، یہى ان كے علم كى انتہا ہے۔ اگر عقل وفہم ركھتےتو یقینا یہ جان لیتے كہ یہ محرومى ان كى معصیت كى وجہ سے ہے اور معصیت پر دینوى ودینى دونوں سزائیں دى جاسكتى ہیں اور یہى وجہ ہے كہ الله نے فرمایا : (بل كانوا لا يفقهون إلا قليلًا) (السعدى: ۷۹۳)\nمنافقین كى خیبر كى غنیمتوں سے محرومى كا حقیقى سبب كیا ہے؟\nwords\nنَكَثَبيعت كو توڑا.\nالمُخَلَّفُونَجو آپ كے ساتھ مكه سے نكلنے سے پيچھے – ره گئے.\nالأَعرَابِبدو/ ديهاتي.\nلَن يَنقَلِبَوه هر گز نهيں پلٹے گا.\nظَنَّ السَّوءِبدگماني۔ كه الله تعاليٰ هرگز اپنے نبي كي مدد نهيں كرے گا.\nبُورًاوه هلاك هونے والے؛ جن ميں كوئي خير نه هو.\nأَعتَدنَاهم نے تياركيا."]])